programs.sol:
"""A visible-document opening response, strongest for capitalized tokens.

A row start or document boundary starts an opening run of identical tokens.
Only that run receives a sizeable prediction; later tokens are predicted zero.
The size is a coarse estimate from writing-system and token-shape classes;
it deliberately does not memorize individual words or token IDs.
"""
import regex

READS = ()


def opening_value(token):
    text = token.strip()
    if text == '<|im_start|>':
        return -3.6
    if text.startswith('<|'):
        return 0.0
    if not text:
        return -0.1
    if '\ufffd' in text:
        return -1.3
    if text.isdecimal():
        return -1.25
    if not any(char.isalpha() for char in text):
        return 0.2
    if text.isascii() and text.isalpha():
        if len(text) == 1:
            return -2.2 if text.isupper() else -1.2
        if text.istitle():
            return -4.7
        if text.isupper():
            return -4.0
        if text.islower():
            return -2.8 if token.startswith(' ') else -3.5
        return -3.0
    if regex.search(r'\p{Script=Han}', text):
        return -3.6
    return -2.1


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = opening_value(prefix.token_strings[-1])
        carry = (document, token_id, True, value)
    elif carry[2] and token_id != carry[1]:
        carry = (document, carry[1], False, carry[3])
    return carry, carry[3] if carry[2] else 0.0

"""Approximate an adverbial-phrase response, especially 'in ... way(s)'.

Manner, viewpoint, degree and reason phrases get positive responses; ordinary
route/possessive uses of 'way' get much less. 'As follows' is another strong
pattern. Space-prefixed line-break tokens give a separate negative response.
The numbers are fitted activation scales, not probabilities. This deliberately
leaves other lexical variation unexplained and keeps only a short text suffix.
"""
import re

READS = ()

# Noun head: ordinary response, extra response in an 'in ...' complement.
ADVERBIAL_HEADS = {
    'way': (0.94, 3.33),
    'ways': (1.08, 3.47),
    'manner': (0.26, 1.48),
    'fashion': (-0.05, 1.18),
    'sense': (0.14, 1.44),
    'respect': (-0.16, 1.24),
    'respects': (0.84, 1.49),
    'regard': (0.09, 1.49),
    'regards': (0.24, 0.06),
    'extent': (-0.13, 0.0),
    'reason': (0.10, 0.0),
    'reasons': (0.09, 0.0),
}
# These typically mark a route, rather than a manner of doing something.
ROUTE_MARKERS = {
    'the', 'my', 'your', 'his', 'her', 'its', 'our', 'their',
    'on', 'by', 'along', 'under', 'off',
}
# Pronouns, auxiliaries, and intervening prepositions break a noun modifier.
PHRASE_BREAKS = {
    'is', 'are', 'was', 'were', 'be', 'been', 'am', 'have', 'has',
    'had', 'can', 'could', 'will', 'would', 'should', 'it', 'he',
    'she', 'they', 'we', 'you', 'i', 'on', 'by', 'under', 'along',
    'into', 'from', 'with', 'as', 'to', 'for',
}
REFERENCE_DETERMINERS = {'this', 'that', 'every', 'any', 'all', 'several', 'many'}


def modifiers(before, preposition):
    """A short, uninterrupted modifier phrase after the nearest preposition."""
    occurrences = list(re.finditer(r'\b' + preposition + r'\b', before, re.I))
    if not occurrences:
        return None
    tail = before[occurrences[-1].end():]
    if not re.fullmatch(r"(?:\s+[\w'-]+){0,5}\s*", tail):
        return None
    words = tail.lower().split()
    if any(w in PHRASE_BREAKS for w in words):
        return None
    if len(words) > 1 and words[-1] in ('that', 'which', 'who'):
        return None  # probably the start of a relative clause
    return words


def predict(token, before):
    value = 0.004
    if token.isspace() and token.startswith(' ') and '\n' in token:
        return value - (0.505 if token.count('\n') >= 2 else 0.086)
    word = token.strip().lower()
    if word not in ADVERBIAL_HEADS and word != 'follows':
        return value
    if not token[:1].isspace() and before[-1:].isalpha():
        return value  # a suffix inside a larger word, not a word head
    previous_words = before.lower().split()
    last = previous_words[-1] if previous_words else ''
    if word == 'follows':
        return value + (2.36 if last == 'as' else 0.0)
    base, gain = ADVERBIAL_HEADS[word]
    value += base
    if word == 'way':
        if last in ROUTE_MARKERS:
            value -= 0.94
        if last == 'same':
            value += 0.21
    mods = modifiers(before, 'in')
    if mods is not None and last not in ROUTE_MARKERS - {'the'}:
        scale = 0.15 if last == 'the' else 1.0
        if word == 'ways' and any(w.isdigit() for w in mods):
            scale = 0.25  # counting alternatives rather than describing manner
        value += gain * scale
        if word in ('way', 'ways'):
            if last in ('a', 'an'):
                value += 2.33
            if 'any' in mods:
                value += 3.08
            if 'no' in mods:
                value += 0.17
            if last in ('this', 'that'):
                value -= 0.65
            if last in ('same', 'following'):
                value -= 0.27
            if word == 'way' and last == 'another':
                value -= 2.18
            if word == 'ways' and not mods:
                value += 1.49
        if word == 'manner' and last in ('a', 'an'):
            value += 1.36
        if word in ('respect', 'respects'):
            if REFERENCE_DETERMINERS.intersection(mods):
                value += 3.72
    if word == 'extent' and modifiers(before, 'to') is not None:
        value += 0.64
    if word in ('reason', 'reasons') and modifiers(before, 'for') is not None:
        value += 0.61 if word == 'reason' else 0.97
    if word in ('regards', 'respects') and modifiers(before, 'as') is not None:
        value += 1.43 if word == 'regards' else 1.30
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (document, (before + token)[-110:]), float(value)

"""A lexical detector for mathematical notation, not a calculator.

Trigonometric and logarithmic names give strong positive signals. Finishing
split function names strengthens them. Roots, other operators, exponential
notation, and a multiplied ten give smaller signals; immediate single-letter
arguments get weak negatives. Recent formula syntax gates prose and code
homographs. Separate rules cover doubled middle dots and an opening Title:
header. The 200-character context buffer resets at document boundaries.
"""
import re

READS = ()
TRIG = {'sin': 5.0, 'cos': 5.4, 'tan': 6.0,
        'cot': 7.5, 'sec': 6.0, 'csc': 7.0}
SMALL = {'sqrt': 2.2, 'cbrt': 2.2, 'floor': 3.0, 'ceil': 2.0,
         'gcd': 2.3, 'lim': 1.6, 'sum': 0.9, 'int': 0.8,
         'vec': 1.1, 'hat': 0.9, 'partial': 1.1, 'tilde': 1.0,
         'left': 0.7, 'mod': 0.7, 'min': 0.2, 'max': 0.2,
         'abs': 1.0, 'angle': 0.5}
WORD = re.compile(r'[^\W\d_]+\Z')
MATH = re.compile(
    r'[=\\^$×²³√]|[α-ω]|\b(?:sin|cos|tan|cot|sqrt|log|ln|angle|'
    r'equation|derivative|integral|calculus|trigonometric)\b')
TEN = re.compile(r'(×|\\times|\*|(?<=\d)x|\bx)\s*1\Z')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    joined = history + token
    m = WORD.search(joined)
    word = m[0] if m else ''
    name = word if word.islower() else ''
    if token.startswith('_'):
        name = ''
    # Completing a split function name produces an especially strong signal.
    split = bool(word and len(word) > len(token.lstrip()))
    formula = bool(MATH.search(history))
    escaped = bool(m and joined[:m.start()].endswith('\\'))
    value = 0.0
    if name in TRIG:
        if name == 'sec':
            formula = escaped or bool(re.search(
                r'\b(?:sin|cos|tan|cot|angle|derivative|calculus)', history))
        value = TRIG[name] if formula or escaped else {
            'sin': 1.2, 'cos': 2.5, 'tan': 0.8,
            'cot': 1.5, 'sec': 0.4, 'csc': 2.0}[name]
        if split:
            value += 3.0
    elif name.startswith(('arc', 'a')) and name in {
            'arcsin', 'arccos', 'arctan', 'arccot', 'arcsec', 'arccsc',
            'arcs', 'arcc', 'arct', 'asin', 'acos', 'atan'}:
        value = (9.5 if split else 5.0) if formula else 1.0
    elif name in {'sinh', 'cosh', 'tanh', 'coth', 'sech', 'csch'}:
        value = (7.5 if split else 4.0) if formula else 0.5
    elif name in {'log', 'ln', 'lg'}:
        code = bool(re.search(
            r'console|logger|logging|export|function\s*\w*\s*\(|const |;|=>|'
            r'logInfo|\b(?:cp|sudo|mkdir)\b|&&', history[-160:]))
        receiver = re.search(r'(?:np|numpy|Math|math)\.?\Z', history)
        immediate = bool(re.search(r'[0-9=+*/^$-]\s*\Z', history))
        if escaped:
            value = 5.5 if name == 'log' else 4.7
        elif name == 'ln':
            shell = re.search(r'&&|\b(?:sudo|mkdir|cp)\b', history[-160:])
            value = 0.0 if shell else 4.9
        elif receiver:
            value = 5.5
        elif token.startswith(('.', '/')):
            value = 0.0
        elif code:
            value = 0.0
        else:
            value = 5.5 if immediate or formula else 1.5
    elif name in SMALL:
        if name == 'sqrt':
            value = 2.8 if split else (1.4 if escaped else 2.2)
        elif name in {'int', 'sum', 'vec', 'hat', 'partial', 'tilde', 'left'}:
            value = SMALL[name] if escaped else 0.0
        else:
            value = SMALL[name] if formula or escaped or name == 'cbrt' else 0.0
    elif name in {'arg', 'det', 'dim'} and escaped:
        value = 7.0 if name == 'arg' else 3.0
    elif word in {'Re', 'Im'} and escaped:
        value = 4.2 if word == 'Re' else 5.5
    elif name in {'sgn', 'erf', 'erfc'} and formula:
        value = 6.0 if name == 'sgn' else 2.0
    elif name == 'exp':
        immediate = re.search(r'[=+*/(-]\s*\Z', history)
        value = 4.6 if escaped else (3.5 if formula and immediate else 0.0)
    elif name == 'e' and (
            token == '*e' or (formula and re.search(r'[={($]\s*$', history))):
        value = 1.3 if token == '*e' else 0.6
    elif token.strip() == '√':
        value = 2.0
    elif token == '··':
        value = 1.7
    elif token == ':' and history == 'Title':
        value = 8.12
    elif len(token.strip()) == 1 and token.strip() in 'αβθφγδxyzts':
        if re.search(r'(?:sin|cos|tan|cot|sec|csc)[²³]?\s*\Z', history):
            value = -0.9 if token.strip() in 'αβθφγδ' else -0.6
    elif token == '0' and TEN.search(history):
        value = 1.2 if TEN.search(history)[1] == '*' else 4.5
    return (doc, joined[-200:]), value

"""A small detector for command arguments and programming syntax.

Option-starting dashes are positive, strongest immediately after shell commands;
path-starting slashes are weaker positives. Indented control words are negative,
strongly so in parenthesized C-like syntax, less in Go/Rust, and least in Python.
Quoted-key JSON openings are negative too. Small filename, import and checklist
corrections accompany these rules; all other tokens are predicted near zero.
The only memory is the previous token and 1,200 recent characters, reset per doc.
"""
import re

READS = ()
FILTERS = {'grep', 'egrep', 'fgrep', 'tail'}
READERS = {'cat', 'head', 'sed', 'awk', 'ls'}
COMMANDS = {
    'python', 'python2', 'python3', 'node', 'bash', 'sh', 'java', 'ruby',
    'perl', 'php', 'rm', 'cp', 'mv', 'mkdir', 'chmod', 'curl', 'wget',
    'find', 'echo', 'printf', 'sort', 'uniq', 'wc', 'tar', 'git', 'diff',
    'ssh', 'docker', 'gcc', 'g++', 'make', 'pytest', 'jest', 'npm', 'pip',
    'ssh-keygen', 'ssh-keyscan', 'ssh-copy-id', 'gunzip', 'gzip',
    'apt-get', 'pacman', 'hdiutil', 'ditto', 'chown', 'ffmpeg', 'packer',
    'pip3', 'pnpm', 'yarn', 'npx', 'mvn', 'cargo', 'go',
}
SUBCOMMANDS = {
    'install', 'uninstall', 'test', 'run', 'build', 'checkout', 'restore',
    'status', 'log', 'add', 'commit', 'fetch', 'clone', 'show', 'push',
    'pull', 'attach', 'detach',
}
SHELL_WORDS = COMMANDS | READERS | FILTERS
# Columns: C-like, Go/Rust-like, Python-like, unknown syntax.
CONTROL = {
    'if':      (-0.81, -0.27, 0.05, -0.09),
    'for':     (-0.93, -0.38, -0.30, -0.18),
    'while':   (-0.58, 0.00, 0.06, 0.00),
    'foreach': (-0.83, -0.80, -0.80, -0.80),
    'switch':  (-0.75, -0.30, -0.30, -0.40),
}
OPTIONS = {' -', ' --', " '--", ' `-'}
SPECIAL = OPTIONS | {
    ' /', ' ./', ' &&', '{"', ' {"', '.sh', '.py', '.md', ' ✓', 'import',
}


def syntax(text):
    """Infer syntax from already visible statements and language conventions."""
    text = text.replace('\\n', '\n')
    if re.search(r'\b(?:func|defer|fn|impl)\b|:=|let mut|\.unwrap\(', text):
        return 1
    statements = list(re.finditer(
        r'(?:^|\n)[ \t+\-\d]*(?:if|for|while)\s*([^\s])[^\n]*', text))
    if statements:
        last = statements[-1]
        if last[1] == '(':
            return 0
        return 2 if last[0].rstrip().endswith(':') else 1
    if re.search(r'\b(?:def|elif|except)\b|self\.', text):
        return 2
    if re.search(r'[;{}]|\b(?:function|public|private|void|const)\b', text):
        return 0
    return 3


def predict(token, previous, text):
    word, prev = token.strip(' \t'), previous.strip()
    if word in CONTROL:
        if previous.isspace() or token.startswith('\t') or previous.endswith('\n'):
            return CONTROL[word][syntax(text)]
        return (-0.39 if prev == 'else' else 0.03) if word == 'if' else 0.001
    if token not in SPECIAL:
        return 0.001
    if token == '{"':
        return -0.576 if previous.endswith('\n') else -0.18
    if token == ' {"':
        return -0.155
    if token in {'.sh', '.py', '.md', ' ✓', ' ./'}:
        return {'.sh': 0.44, '.py': 0.11, '.md': 0.11,
                ' ✓': -0.16, ' ./': 0.44}[token]
    if token == 'import':
        return -0.29 if previous.rstrip('\r\n').endswith(';') else 0.001
    match = re.search(r'([A-Za-z][\w.+-]*)$', text)
    last_word = match[1] if match else ''
    recent = text[-400:].replace('\\n', '\n')
    shell = bool(set(re.findall(r'[A-Za-z][\w+-]*', recent)) & SHELL_WORDS)
    if token in OPTIONS:
        if last_word in FILTERS:
            return 2.65
        if last_word in READERS:
            return 2.17
        if last_word in COMMANDS or (shell and last_word in SUBCOMMANDS):
            return 1.92
        if shell:
            if '--' in token:
                return 1.48
            if re.search(r'\bfind\s+[^\n]*$', recent):
                return 0.53
            if re.search(r'\.(?:py|js|sh)(?:[\w./-]*)$', text):
                return 1.85
            if last_word:
                return 0.20
    if token == ' /':
        if last_word == 'cd':
            return 1.01
        if last_word in SHELL_WORDS or prev in {'>', '>>'}:
            return 1.02
        if prev in {'\\"', "'"}:
            return 0.69
        if prev in {'on', 'of', 'at'}:
            return 0.24
        if prev == ':':
            return 0.16
    if token == ' &&' and shell:
        return 0.39
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, text)
    return (doc, token, (text + token)[-1200:]), value

programs.haiku:
"""Shell-argument starts: the dash of a command-line flag, a path or a pipe that follows a
shell command name on the same line (e.g. `tail -n`, `cargo test --`, `cd /testbed`,
`cat go.mod | grep`). They fire most when they come right after the command name, and
fade with distance. Code's statement-opening `if`/`for`/`while` and the `{"` that opens a
tool call go slightly negative. Everything else is predicted as 0."""
import re

READS = ()

# Common command-line tools, as words.
COMMAND = re.compile(
    r"\b(grep|cat|tail|head|cargo|npm|npx|pytest|python3?|git|curl|ssh|ssh-keygen|sed|ls|make|"
    r"docker|rustc|go|pip3?|cd|find|xargs|wc|sort|awk|rm|cp|mv|mkdir|echo|node|yarn|bash|"
    r"apt|kubectl|tar|chmod|chown|diff|tsc|mvn|gradle|wget|unzip|ffmpeg|jq|rg|hdiutil|ditto|"
    r"ssh-keyscan|ssh-copy-id|sleep)\b"
)
FLAG_DASHES = {" -", " --"}
PATH_START = {" /"}
PIPE = {" |"}
STATEMENT_KEYWORDS = {" if", " for", " while", "\tif", "\tfor"}


def step(carry, prefix, upstream):
    # carry: (document id, text of the current line so far)
    doc = prefix.document_ids[-1]
    line = carry[1] if carry is not None and carry[0] == doc else ""
    tok = prefix.token_strings[-1]
    before = line
    line = "" if ("\n" in tok or tok == "\\n") else line + tok

    # characters between the last command name on this line and this token
    last = None
    for m in COMMAND.finditer(before):
        last = m
    gap = len(before) - last.end() if last else 999

    if tok in FLAG_DASHES or tok in PATH_START or tok in PIPE:
        if tok in FLAG_DASHES:
            strength = 2.0
        elif tok in PATH_START:
            strength = 1.0
        else:
            strength = 0.6
        value = strength if gap < 8 else strength / 2 if gap < 32 else 0.0
    elif tok in STATEMENT_KEYWORDS and before.strip() == "":
        value = -0.7
    elif tok == '{"' and before.strip() == "":
        value = -0.6
    else:
        value = 0.0
    return (doc, line), value

"""Component layers.1.mlp.down_proj:4102 as a "newcomer / beginner" detector.

What it does, in plain terms:
- It goes strongly negative on words for a beginner or newcomer: "beginner(s)",
  "novice", "newbie", "newcomer(s)", "timers" (first-timers), "freshman", "newer",
  and "初めて" / "学者" (Japanese/Chinese for first-time / beginner).
- On "to" right after "new" ("new to yoga", "are new to") it goes strongly negative,
  and more mildly after unfamiliarity adjectives ("native to", "endemic to",
  "unique to", "specific to", "foreign to", "stranger to").
- On "new" used as a predicate of being inexperienced ("are new", "is new",
  "be new", "am new") it is negative; on other "new" it is weakly negative.
- On the word right after "New" in novelty or place-name phrases ("new low",
  "new normal", "New Heights", "New England") it is positive; "New Year" is negative.
- "just starting" is negative.
Everywhere else it predicts 0.

Why: the component's sign tracks "is this about being new/inexperienced" versus
"novelty/proper name". Its biggest values are on the word "to" that follows "new"
(the model is about to say "new to ..."). Only prefix tokens are read, so the
program is causal.
"""
READS = ()

BEGINNERS = {" beginner", " beginners", " novice", " novices", " newbie", " newcomer", " newcomers",
             " timers", " freshman", " newer", "初めて", "学者"}
NOVELTY = {" low", " high", " normal", " era", " level", " window", " Heights", " Roman",
           " Hope", " South", " England", " Jersey", " Haven"}
UNFAMILIAR = {" native", " endemic", " unique", " specific", " foreign", " stranger"}
BE = {" are", " is", " be", " am", " 're", "'m", " been"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in BEGINNERS:
        return None, -4.0
    if cur == " to":
        if prev in (" new", " New"):
            return None, -11.5
        if prev in UNFAMILIAR:
            return None, -2.4
        return None, 0.0
    if prev in (" new", " New"):
        if cur == " Year":
            return None, -6.5
        if cur in NOVELTY:
            return None, 2.6
        return None, 0.0
    if cur == " starting" and prev == " just":
        return None, -7.0
    if cur in (" new", " New"):
        if prev in BE:
            return None, -4.0
        return None, -0.35
    return None, 0.0

programs.sol:
"""Approximate the component's document-initial pulse from the token's spelling.

Hold the pulse through identical leading repeats, then output zero. English
function-word classes, character types and leading spaces set coarse levels;
individual-word variation is deliberately left unexplained.
"""
import unicodedata

READS = ()


# Closed English grammatical classes, not an arbitrary token lookup.
FUNCTION_LEVELS = (
    (frozenset("a an the".split()), -0.4),  # Articles.
    (frozenset(("i you he she it we they me him her us them "
                "my your his its our their mine yours hers ours theirs").split()),
     3.6),  # Personal pronouns and their possessives.
    (frozenset(("am is are was were be been being do does did have has had "
                "will would shall should can could may might must").split()),
     5.4),  # Auxiliary and modal verbs.
    (frozenset(("in on at by for from to of with without over under into "
                "through between about before after").split()),
     1.6),  # Prepositions.
    (frozenset("and or but nor so yet".split()), 1.1),  # Coordinators.
)


def initial_value(s):
    text = s.strip()
    if s == '<|im_start|>':
        return 6.23
    if s.startswith('<|'):
        return 0.0
    if not text:
        return 0.14
    c = text[0]
    if c.isdigit():
        return -0.85
    if c.isalpha():
        for words, level in FUNCTION_LEVELS:
            if text.lower() in words:
                return level
        if not c.isascii():
            return 4.5
        if len(text) == 1:
            return 0.7
        return 2.6 if s[0].isspace() else 3.2
    if c in ',;:':  # Clause separators.
        return -1.7
    kind = unicodedata.category(c)
    if kind in ('Pe', 'Pd', 'Sc', 'Sm'):
        return -0.9  # Closing brackets, dashes, currency and math signs.
    if kind == 'Ps':
        return -0.5  # Opening brackets.
    if kind == 'Pc':
        return 3.5  # Connector punctuation, such as an underscore.
    if len(text) > 1 and len(set(text)) == 1:
        return 1.5
    return 1.2 if c.isascii() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        first = token
        value = initial_value(prefix.token_strings[-1])
    else:
        _, first, value = carry
        if token != first:
            value = 0.0
    return (doc, first, value), value

"""Detect written character escapes, with a negative response to tsu-family kana.

The large positive responses mark numeric quote/apostrophe escapes and names
of non-whitespace HTML entities. Split names are stronger than some merged
spellings.
A terminating semicolon has a smaller response; mojibake punctuation also
fires. Japanese tsu/zu spellings produce negative responses. Most other
text is close to zero. Nearby kana and particles scale the tsu response.
Document-initial title and escaped blockquote punctuation also fire.
"""
import html.entities
import re
import unicodedata

READS = ()
_ENTITY = re.compile(r'&(?:amp;)?([A-Za-z][A-Za-z0-9]*|#[0-9]+)$')
_NAMES = {**html.entities.name2codepoint, 'apos': ord("'")}
PARTICLES = frozenset('をがはにとのもでへや')


def response(token, previous, history, position, raw=b'', previous_character=''):
    """Predict from the spelling pattern ending at this token."""
    if token == ':' and previous == 'Title' and position == 1:
        return 6.9
    if token == ';' and previous == '&gt' and position == 1:
        return 6.4
    if token.startswith(';'):
        match = _ENTITY.search(history)
        if match and (match[1] in _NAMES or match[1][1:].isdigit()):
            if token == ';s':
                return -0.2
            if token.startswith(';/'):
                return 4.0
            if match[1] == '#39':
                return 3.8
            if match[1] == '#34':
                return 2.2
            return 1.5 if match[1].startswith('#') else 1.0
    # A bare hash still gives a weaker version of the quote-code response.
    if history.endswith('#3') and not history.endswith('&#3'):
        if token == '9':
            return 8.3
        if token == '4':
            return 4.1
    match = _ENTITY.search(history + token)
    if match:
        name = match[1]
        if name == '#39' and token == '9':
            return 13.3
        if name == '#34' and token == '4':
            return 8.9
        if name in _NAMES and any(c.isalpha() for c in token):
            character = chr(_NAMES[name])
            if not character.isspace():
                merged = '&' in token
                if character == "'":
                    return 14.2
                if character == '"':
                    return 4.0 if merged else 6.4
                if character == '<':
                    return 9.2
                if character == '>':
                    return 6.3 if merged else 7.8
                if character == '&':
                    if merged:
                        return 8.5
                    if previous.strip() != '&':
                        return 6.5
                    return 12.1
                return 8.0
    if '\ufffd' in token:
        completed = raw.decode('utf-8', errors='replace')[-1:]
        if completed in ('つ', 'ツ'):
            return -3.2
        if completed in ('ず', 'づ', 'っ', 'ッ'):
            token = completed
    if token == '€' and previous.endswith('â'):
        return 3.1
    if token == '‰' and previous.endswith('â'):
        return 1.0
    if token in ('つ', 'ツ'):
        # Use the preceding script/particle as a proxy for word-internal kana.
        ch = previous_character or previous[-1:]
        name = unicodedata.name(ch, '') if ch else ''
        if token == 'つ':
            if previous in PARTICLES:
                return -1.8
            if name.startswith('HIRAGANA'):
                return -4.0
            if name.startswith('CJK'):
                return -2.0
            return -1.5
        if name.startswith('KATAKANA'):
            if 'SMALL' in name or ch == 'ン':
                return -2.3
            return -4.1
        return -1.5
    if token in ('ず', 'づ'):
        return -1.8
    if token == 'ズ':
        return -0.4
    if token in ('っ', 'ッ'):
        return -0.4
    if token == 'いつ':
        return -3.5
    if token in ('つか', 'つき', 'つく', 'つけ'):
        return -0.8
    if token == 'っち':
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, history, raw_history = 0, '', '', b''
    else:
        _, position, previous, history, raw_history = carry
    token = prefix.token_strings[-1]
    raw = raw_history + prefix.token_bytes[-1]
    previous_character = raw_history.decode('utf-8', errors='replace')[-1:]
    value = response(token, previous, history, position, raw, previous_character)
    carry = (document, position + 1, token, (history + token)[-64:], raw[-4:])
    return carry, value

"""Approximate a spelling-cluster response, chiefly around the letter D.

DV/ADV and DJ fragments tend to give negative values; D followed by L or N
usually gives positive values. Splitting such spellings across tokens
makes a difference. The rules distinguish fragments, common suffixes,
uppercase letter sequences, and name-ending shapes like -land and -lin.
Cyrillic spellings are transliterated before applying the same rules.
This is a partial orthographic explanation, not a semantic classifier.
"""
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

# Responses when the previous token ends in D and this one continues it.
FOLLOWING_D = {'j': -1.68, 'l': 0.68, 'n': 0.88, 'v': -2.14}
SINGLE_LETTER = {'j': -1.17, 'l': 1.21, 'n': 1.74, 'v': -0.91}
LONG_FRAGMENT = {'j': 1.60, 'l': -0.32, 'n': -0.51, 'v': 2.09}
GRAMMATICAL_SUFFIX = {'j': 0.54, 'l': -0.43, 'n': -0.78, 'v': -1.01}
AFTER_AD_PREFIX = {'j': -1.71, 'l': 0.95, 'n': 0.83, 'v': -3.83}
UPPERCASE_SEQUENCE = {'j': 0.32, 'l': 0.96, 'n': 0.57, 'v': 0.40}
CONSONANT_BEFORE_D = {'j': 1.05, 'l': -0.38, 'n': -0.18, 'v': 0.63}
NAME_ENDINGS = {'land': 3.18, 'ley': 0.94, 'lin': 4.09, 'ner': 3.76}

# Whole tokens can themselves be these fragments or word families.
ADV_RESPONSE = {
    'fragment': -4.62,
    'advocate': -4.91,
    'advise': -2.87,
    'other_advis': -1.05,
    'advent': -3.94,
    'advert': -2.54,
    'advers': -1.46,
    'other': -0.36,
}
CLUSTERS = {'adj': -1.52, 'dj': -1.16, 'dl': 0.94,
            'dn': 0.91, 'dv': -1.55}


@lru_cache(maxsize=8192)
def normalize(text):
    return regex.sub(r'\p{Script=Cyrillic}+',
                     lambda m: anyascii(m[0]), text).lower()


def response(previous, token):
    p, s = normalize(previous), normalize(token)
    bare = s.lstrip()
    attached = bool(s and s[0].isalpha())
    camelcase = bool(token and token[0].isupper()
                     and not previous.isupper())
    value = 0.0
    if p.endswith('d') and attached and not camelcase:
        letter = s[0]
        if letter in FOLLOWING_D:
            value += FOLLOWING_D[letter]
            adjustments = (
                (len(s) == 1, SINGLE_LETTER),
                (len(s) >= 5, LONG_FRAGMENT),
                (s.endswith(('ed', 'ing', 'ly', 'less', 'ness')),
                 GRAMMATICAL_SUFFIX),
                (p.lstrip() == 'ad', AFTER_AD_PREFIX),
                (token.isupper() and previous.isupper(), UPPERCASE_SEQUENCE),
                (p[-2:-1] in ('n', 'l', 'r'), CONSONANT_BEFORE_D),
            )
            for matches, table in adjustments:
                if matches:
                    value += table[letter]
            ending = 'land' if s == 'lands' else s
            value += NAME_ENDINGS.get(ending, 0.0)
            if letter == 'v' and regex.search(r'\p{Script=Cyrillic}', token):
                value += 1.04
            if (letter == 'n' and token.isascii()
                    and zipf_frequency(s, 'en') > 4.5):
                value -= 0.76
        elif s.startswith('in') and not s.startswith('ing'):
            value += 0.40
            if s.startswith('inn'):
                value += 1.97
        elif s.startswith(('hl', 'dl')):
            value += 1.63
    if bare.startswith('adv'):
        if bare == 'adv':
            family = 'fragment'
        elif bare.startswith('advoc'):
            family = 'advocate'
        elif bare in ('advise', 'advises'):
            family = 'advise'
        elif bare.startswith('advis'):
            family = 'other_advis'
        elif bare in ('advent', 'advert', 'advers'):
            family = bare
        else:
            family = 'other'
        value += ADV_RESPONSE[family]
    else:
        value += CLUSTERS.get(bare, 0.0)
    if attached:
        preceding = p.lstrip()
        if preceding == 'adv':
            value -= 1.65
        elif preceding.startswith('advoc'):
            value -= 2.54
        elif preceding.endswith(('dv', 'dj')):
            value -= 0.56
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    return (document, token), response(previous, token)

programs.haiku:
"""Draft 5: the component is negative while a word beginning 'adv' is being spelled out.
The word is rebuilt from the tokens so far (so 'ad' + 'vent' counts as 'advent'). Strongest
for advocate/adv/advent/adverb, medium for advise/advert/adversary/adj, weak for other
adv- words such as advantage, advance, advice."""

import re

READS = ()


def step(carry, prefix, upstream):
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    word = "" if new_doc or carry is None else carry
    word = re.search(r"[A-Za-z]*$", word + prefix.token_strings[-1]).group(0)
    w = word.lower()
    if w.startswith(("advoc", "adven", "adverb")) or w == "adv":
        v = -3.0
    elif w.startswith(("advis", "advert", "advers")) or w == "adj":
        v = -1.25
    elif w.startswith("adv"):
        v = -0.4
    else:
        v = 0.0
    return word, float(v)

programs.sol:
"""A sparse response to roots meaning control or changes in extent/speed.

Chinese/Japanese control, expansion, slowing, shrinking and breadth roots
produce positive pulses, diluted in longer tokens. A root completed from
UTF-8 fragments gives a larger pulse. Immediate word-completing characters
can retain a pulse. Korean '확' and its expansion-word endings behave alike.
Smaller rules cover development, institutions, Java package names, and
document-opening format markers. At document starts, whitespace, punctuation and
code declarations usually receive negative pulses. Other tokens stay near zero.
"""

READS = ()

# Root characters grouped by meaning and orthography, with their pulse sizes.
ROOTS = (
    ("控", 4.0),                 # control
    ("扩擴拡", 4.2),            # expand
    ("拓", 4.5),                # open up
    ("缓", 2.4), ("緩", 2.2),  # slow / relax
    ("缩", 4.0), ("縮", 1.1),  # shrink
    ("宽寬寛阔闊", 1.3),       # wide / broad
)
HEIGHT = {c: height for chars, height in ROOTS for c in chars}
WORD_ENDINGS = {
    "控": "制", "扩": "大展充建", "擴": "大展充建", "拡": "大散",
    "拓": "展宽寬", "缓": "慢", "緩": "慢", "缩": "小短",
    "縮": "小短", "확": "장산대",
}
CODE_TYPES = {"void", "int", "char", "string", "String"}
DECLARATIONS = {"import", "def", "class", "const"}
LOW_CONTROL_WORDS = {"可控", "失控", "控股", "防控", "操控"}


def unfinished_character(data):
    """Keep only an incomplete UTF-8 character for the next token."""
    if not data or data[-1] < 128:
        return b""
    for k in range(1, min(3, len(data)) + 1):
        lead = data[-k]
        needed = (2 if 0xC2 <= lead <= 0xDF else
                  3 if 0xE0 <= lead <= 0xEF else
                  4 if 0xF0 <= lead <= 0xF4 else 0)
        if needed:
            return data[-k:] if k < needed else b""
    return b""


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b"", "", "")
    _, position, pending, previous, previous_root = carry
    raw = prefix.token_bytes[-1]
    data = pending + raw
    text = data.decode("utf-8", "ignore").strip()
    pending = unfinished_character(data)

    value = -0.003
    if position == 0:
        if raw.isspace():
            value = -0.44
        elif text in CODE_TYPES:
            value = -1.2
        elif text in DECLARATIONS:
            value = -0.72
        elif text.startswith(("//", "/*", "#")):
            value = -0.57
        elif text == "<!":
            value = 2.98
        elif text and text.isascii():
            if all(not c.isalnum() for c in text):
                value = -0.2
            elif text[0].isdigit():
                value = -0.12
            elif text[0].isupper():
                value = -0.1
    root = next((c for c in text if c in HEIGHT), "")
    if root:
        if len(text) == 1:
            dilution = 1.0
        elif len(text) == 2:
            dilution = (0.35 if root == "控" else
                        0.2 if root in "缩縮宽寬寛阔闊" else 0.55)
        else:
            dilution = 0.02
        value = HEIGHT[root] * dilution
        if raw and 0x80 <= raw[0] < 0xC0:
            value *= 1.6 if root in "拓缩縮" else 2.1
    if text in LOW_CONTROL_WORDS:
        value = 0.6
    if text == "管控":
        value = 5.0
    if text == "확":
        value, root = 2.35, "확"
    if text and text[0] in WORD_ENDINGS.get(previous_root, ""):
        value += 2.1
    if "发展" in text or "發展" in text:
        value = 0.3
    if "机构" in text or "機構" in text:
        value = -1.0
    if text == "com" and previous == "package":
        value = 1.4
    if text == ":" and previous == "Title" and position == 1:
        value = 4.39
    if position == 0 and text == "<|endoftext|>":
        value = -2.33

    last_root = root if len(text) == 1 else ""
    return (doc, position + 1, pending, text, last_root), value

"""A surface-form approximation to a mostly document-initial feature.

Most measured activation energy occurs at the first two document tokens.
Letters, digits, articles, question words, punctuation and code/header openers
receive distinct onset responses; other alphabetic words get a small
negative baseline. Repeated initial tokens retain their onset response.
A document-initial Title: has a large negative response on the colon.
Later tokens are silent except for doubled backslashes: recent TeX commands
or a newline in the token suggest a positive formula row break; otherwise
it predicts a negative string escape.
This deliberately omits most fine-grained word-identity variation.
"""
import re

READS = ()


def initial(token):
    word = token.strip()
    if len(word) == 1 and word.isupper():
        value = 3.14 if word == 'A' else 2.51 if word == 'I' else 1.4
        return value * (0.6 if token != word else 1.0)
    if word in ('0', '1', '9'):
        return {'0': 2.21, '1': 1.87, '9': 1.39}[word]
    if token in ('a', ' a', 'The', 'the', ' The'):
        return {'a': 2.9, ' a': 1.45, 'The': -0.57,
                'the': -1.29, ' The': 0.86}[token]
    if len(word) == 1 and word.isascii() and word.islower():
        return 1.2 if token == word else 0.5
    if word in ('We', 'You'):
        return 1.7
    if word in ('Is', 'Are', 'Be', 'Will'):
        return -2.7
    if word in ('How', 'What', 'When', 'Where', 'Who', 'Why'):
        return 1.5
    if token in ('In', 'in', ' In'):
        return 1.6
    if word in ('Title', 'Question'):
        return 2.84 if word == 'Title' else 4.43
    if token.startswith('#include'):
        return 2.84
    if word in ('import', 'package'):
        return 1.48 if word == 'import' else -1.24
    if token.startswith('/*'):
        return 2.0
    if token.startswith('//'):
        return 1.15
    if word in ('"', "'", '“', '‘'):
        return -2.7 if token == word else -1.5
    if token and set(token) == {' '} and len(token) in (2, 4, 6, 8):
        return 1.8
    if word and set(word) == {'·'}:
        return 0.755
    if token == '<|im_start|>':
        return 0.387
    if word.isascii() and word.isalpha():
        return 0.35 if word.isupper() else -0.45
    return 0.0


MATH = re.compile(r'\\(?:begin|end|frac|sqrt|left|right|mathrm|'
                  r'hfill|nonumber|qquad|text|alpha|sigma|int)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
        first, repeated, recent = token, True, ''
    else:
        _, position, previous, first, repeated, recent = carry
        position += 1
        repeated = repeated and token == first
    value = 0.0
    if repeated:
        value = initial(token)
    elif position == 1 and previous == 'Title' and token == ':':
        value = -12.32
    elif position == 1 and previous == '1' and token == '2':
        value = -1.82
    elif token.count('\\') >= 2:
        value = 1.05 if MATH.search(recent) or '\n' in token else -0.75
    recent = (recent + token)[-160:]
    return (doc, position, token, first, repeated, recent), value

programs.haiku:
"""Layer-1 MLP down-projection, unit 4111: a document-start detector.

The unit is nearly silent except at the first two tokens of a document (the model resets
at each <|endoftext|>-separated document). At the first token its value depends on which
token it is:
  - single letters and digits (A, I, Q, 0, 1) and words that open a question or heading
    (How, What, You, There, Title, ...) push it up;
  - quotation marks, identifiers with _ or ., and lowercase or space-prefixed words push it down.
At the second token it is strongly negative (about -12) when the document starts with
"Title" and the next token is ":"; otherwise near 0. Everywhere later it is near 0.
"""

READS = ()

OPENERS = frozenset(
    "How What Why Who When Where Which You We There Let Here Question Title Name In I A Q".split()
)


def first_token_value(s):
    core = s.strip()
    if not core:
        return 0.0
    if core in OPENERS:
        return 1.8
    if len(core) == 1 and core.isalnum():
        return 0.9
    if core[0] in "\"“”'‘’":
        return -1.0
    if core[0] in "#/<$@%\\*":
        return 0.4
    if "_" in core or "." in core:
        return -0.5
    if core.islower():
        return -0.4
    return -0.35


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        # first token of a document: a new (doc, offset, first token) state
        return (doc, 0, s), first_token_value(s)
    _, offset, first = carry
    if offset == 0 and first == "Title" and s == ":":
        value = -12.0
    else:
        value = 0.0
    return (doc, offset + 1, first), value

programs.sol:
"""A token-shape-dependent pulse at the beginning of each document.

Source-code opening syntax is strongly positive. Ordinary words are near zero,
single capital letters and some pronouns lean negative; Han/Cyrillic text
leans positive. NUL at a document start gives a particularly large pulse.
Initial homogeneous runs of carriage returns or mid-dot padding also respond.
Other later activations are approximated by zero. These rules capture the
start effect, not the finer word-specific variation.
"""
import unicodedata

READS = ()


def opening_value(s):
    if s == '\x00':
        return 13.5
    if s == '\r':
        return -2.49
    if s and not s.strip('·'):
        return 0.78
    if s == '<|endoftext|>':
        return 4.48
    if s.startswith('<|'):
        return -0.54
    if s.startswith(('#include', '#pragma')):
        return 8.2
    if s.startswith('#!'):
        return 1.67 if s.startswith('#!/') else 5.5
    if s.startswith('#define'):
        return 2.8
    if s.startswith('#if'):
        return 1.1
    if s.startswith('/*'):
        return 3.1 if '\n' in s else 2.6
    if s == '//':
        return 1.33
    if s.startswith('$('):
        return 10.0
    if s.startswith('('):
        if ')' in s or "'" in s:
            return 1.7
        if '"' in s or (len(s) > 2 and s[1:].isalpha()):
            return 2.2
        return 4.2
    if s.startswith('{'):
        return 2.1 if '\\' in s else 4.3
    if s.startswith(('[', '【', '（')):
        return 2.3 if not s.startswith('（') else 4.4
    if s.startswith(' ('):
        return 0.64
    if s.startswith(' {'):
        return 1.5
    if s.startswith(('"', '“', '\\"')):
        return 1.8
    if s == '\\n':
        return 2.1
    if s == '\r\n':
        return 4.0
    if s.strip() == '':
        return 0.45 if '\n' in s or '\t' in s else -0.25
    if s in ('.\n', '。\n', ':\n', '：\n', ';;\n', ']\n', '-\n'):
        return 2.0
    if s.startswith('#'):
        return -1.0
    word = s.strip()
    if word.isdigit():
        return -0.2
    if word.isascii() and word.isalpha():
        if len(word) == 1 and word.isupper():
            return -1.05
        if word.lower() in {'i', 'we', 'you', 'my', 'your', 'our', 'their'}:
            return -1.1
        return -0.2
    if word and all('CJK UNIFIED' in unicodedata.name(c, '') for c in word):
        return 0.75
    if word and all('CYRILLIC' in unicodedata.name(c, '') for c in word):
        return 0.45
    if word and all(unicodedata.category(c).startswith('P') for c in word):
        return -0.5
    return -0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    first = carry is None or carry[0] != doc
    uniform = first or (carry[2] and raw == carry[1])
    # Long homogeneous runs matter for carriage-return and mid-dot padding.
    padding = token == '\r' or (token and not token.strip('·'))
    value = opening_value(token) if first or (uniform and padding) else 0.0
    return (doc, raw, uniform), value

programs.haiku:
"""Layer 1, MLP down-projection, component 4112.

What it does: this component is almost silent except on the FIRST token of each document
(and of each packed row). A document's first token gets a value that depends on what kind of
token it is: preprocessor directives such as `#include` push it up hard; opening brackets and
comment openers (`(`, `[`, `{`, `/`) push it up; CJK and Cyrillic text starts and
newline-ending punctuation push it up a little; capitalised English words, digits, and closing
punctuation push it slightly down. Everywhere else the program predicts 0, except the
interpunct token `··`, which gets a small positive value.

The values are class means fitted on training rows (see the notes in the explanation).
"""

READS = ()

INTERPUNCT = "··"
DIRECTIVES = ("#include", "#pragma", "#!", "#define", "#import")
OPENERS = "([{/"
CLOSERS = ",.)]}<|>;:!?"


def _is_cjk(c):
    return "぀" <= c <= "鿿" or "가" <= c <= "힯"


def start_value(s):
    """Predicted activation for a token that opens a document."""
    st = s.strip()
    if not st:
        return 0.0
    c = st[0]
    if st.startswith(DIRECTIVES):
        return 7.0
    if c == "#":
        return -0.65
    if c in OPENERS:
        return 1.5
    if _is_cjk(c):
        return 0.65
    if "Ѐ" <= c <= "ӿ":
        return 0.4
    if c in CLOSERS:
        return 0.7 if "\n" in s else -0.4
    if c.isdigit():
        return -0.2
    if c.isascii() and c.isalpha():
        return -0.35 if c.isupper() else -0.2
    if "\n" in s:
        return 1.3
    return 0.2


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return None, start_value(token)
    return None, 0.5 if token == INTERPUNCT else 0.0

programs.sol:
"""Approximate the component with a syntax-sensitive software-testing signal.

Assign the largest positive values to test declarations and annotations, then
smaller values to test paths, headings, identifiers and ordinary mentions.
Include side responses to code/output punctuation, and negative responses to
receiver/dunder syntax and middle-dot filler. Unmatched tokens predict zero.
Only the previous token and 256 recent characters are kept, per document;
fixed strengths do not capture all the component's contextual variation.
A final 0.85 factor conservatively reduces these approximate responses.
