import re

READS = ()


def response(s, previous, recent):
    p = previous.strip()
    word = s.lstrip(" \t/._-(:@\\")
    lower = word.lower()
    line = re.split(r"\n|\\n", recent)[-1]
    if lower in {"test", "tests"}:
        if p.endswith("#["):
            return 11.6
        if p == "@":
            return 6.5
        if s.startswith("@"):
            return 3.0
        if p == "func":
            return 10.7 if word[0].isupper() else 2.4
        if p == "def":
            return 9.9 if previous[0].isspace() else 8.6
        if p == "void":
            return 9.1
        if p == "function":
            member = re.search(
                r"\b(public|protected|private)\s+function$", recent
            )
            return 10.0 if member else 5.5
        if p == "fn":
            return 4.5
        if p == "class":
            return 5.7
        if p == "::":
            return 4.6 if word[0].isupper() else 5.1
        if s.startswith("/"):
            if previous == "tests":
                return 7.1
            if p in {"/tests", "tests"}:
                return 5.6
            if re.search(r"(?:^|[/_])tests?[/_]", line):
                return 3.4
            if line and re.search(
                r" (?:PASSED|FAILED|SKIPPED)\b[^\n]*\n[^\n]*$", recent
            ):
                return 4.5
            return 1.1 if lower == "tests" else 1.5
        if s.startswith("_") or s.startswith("-"):
            return 0.7
        if s.startswith("."):
            return 1.9
        if lower == "tests":
            if word == "tests" and previous.endswith("\n"):
                return 4.5
            if word[0].isupper() or not s[0].isspace():
                return 2.3
            return 0.86
        if word == "TEST":
            return 7.9 if previous.endswith("\n\n") else 2.9
        if word == "Test":
            if (p in {"#", "//", "*", ":", "==="}
                    or previous.isspace() and "\n" not in previous):
                return 3.4
            if not s[0].isspace() and p and p[-1].isalnum():
                return 1.2
            return 2.1
        if not s[0].isspace():
            return 3.6 if previous.endswith("\n") else 1.8
        if p and set(p) == {"="}:
            return 5.0
        if previous.isspace() or p in {"=", "from", "import", ":", "✓", "#", "//"}:
            return 2.4
        return 0.65
    if lower == "testing":
        return 1.15 if word[0].isupper() else 0.4
    if lower == "tested":
        return 0.2
    if word == "TestMethod" and p == "[":
        return 10.0
    # Type/definition markers following a test annotation.
    if s.strip() in {"void", "fn"} and re.search(
        r"@(?:Before|After)\w*[^{};]{0,70}$", recent
