        return 0.08
    if s.strip() == "function" and p in {"public", "protected", "private"}:
        return 2.6
    if s == ',' and re.search(r"TEST(?:_F)?\([^,;{}]*$", recent):
        return 11.0
    if s.strip() in {"PASS", "FAIL", "RUN"} and p in {"---", "==="}:
        return 2.1 if s.strip() != "RUN" else 0.8
    if '✓' in s:
        return 0.55 if not s.startswith(' ') else 0.75
    if s == '{"' and previous.endswith('\n'):
        return 0.95
    if s == 'def' and (not recent or p == '<|endoftext|>'):
        return 4.7
    if s == '··' and recent.endswith('····'):
        return -1.55
    if s.lstrip().startswith('(') and p == 'func':
        return -4.5 if s.startswith(' (') or s.startswith('(_') else -0.6
    if s.lstrip().startswith('__') and p in {'def', 'function'}:
        return -3.2
    if s.startswith('__') and re.search(r'\bdef __\w+$', recent):
        return -2.9
    if s in {"('", '("'} and p == 'test':
        return 3.6
    if s == '_F' and p == 'TEST':
        return 5.8
    if s.startswith('__') and p.lower().endswith('test'):
        return -1.8
    if s == 'table' and re.search(r'ref-type="$', recent):
        return -2.0
    if s == '(&':
        return -1.9 if re.search(r'\bfn [^()]*$', recent) else -0.15
