        _, previous, recent = carry
    s = prefix.token_strings[-1]
    value = 0.85 * response(s, previous, recent)
    return (doc, s, (recent + s)[-256:]), value

"""Approximate an abbreviation-like full stop using only its left context.

References, months, units, number markers, initials and short capitalized forms
receive positive values. Word frequency helps distinguish truncations from
ordinary words. Comment-ending periods get a smaller response. Most other
tokens are near zero; document starts have a negative offset. These rules do
not reproduce the model's substantial variation between individual words.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Conventional abbreviated references, not a list of model token numbers.
CITATIONS = set('''art chap sect sec par para pp pg vol no nos nr fig figs eq eqs
    col lns doc pat app supp civ crim stat ann dist cir ct cert rev hon pres
    supt gov gen adm prof dir inst univ soc proc sci phys chem biol geol hist
    ser nat fl ib ibid id op cit cf vgl vergl ed eds trans ca ff
    lib cap pag ref rec bibl bibliogr publ
    adj adv conj nom gen dat acc abl instr sing plur pers'''.split())
MONTHS = set('''jan feb mar apr jun jul aug sep sept oct nov dec
    janv fev févr avr juil août déc'''.split())
TITLES = {'mr', 'mrs', 'ms', 'dr'}
INTERJECTIONS = set('hmm hm mhm aha ah huh oh hey wow yes nope'.split())
STATES = set('''ala ariz ark cal calif colo conn del fla ga ill ind kan kans ky
    la mass md me mich minn miss mo mont neb nebr nev okla ore pa penn tenn tex
    va vt wash wis wisc wyo'''.split())
UNITS = {'lb', 'lbs', 'ft', 'qt', 'oz', 'min', 'hr', 'in'}
# Russian monetary units and abbreviated powers of a thousand.
MONEY = {'руб', 'коп', 'тыс', 'млн', 'млрд'}

@lru_cache(maxsize=8192)
def frequency(word):
    return max(zipf_frequency(word, lang) for lang in
               ('en', 'de', 'fr', 'es', 'it', 'pt', 'ru', 'pl', 'nl'))


def predict(token, before):
    value = -0.006
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    # A stop fused to a word (e.g. .com) is usually a different operation.
    stop = re.fullmatch(r'\.([,;:\-\\)]*)', token)
    line = before.rsplit('\n', 1)[-1]
    comment = bool(re.search(r'(^\s*\*|//|#)', line))
    newline = bool(re.fullmatch(r'''[)\]"']*\.\s+''', token))
    newline = newline or (token == '.\\' and comment)
    if not (stop or newline):
        if token == '°' and re.search(r'\b(?:[nN]|[IVXLCDMivxlcdm]+)$', before):
            return 0.55
        if token.startswith('。'):
            return 0.08 if '\n' in token else 0.035
        return -0.09 if token == ' .' else value

    match = re.search(r'([^\W\d_]+)$', before)
    word = match[0] if match else ''
    low = word.lower()
    if newline:
        value = 0.035 if token.count('\n') > 1 else 0.045
        if comment:
            value = 0.34 if token.count('\n') <= 1 else 0.25
        elif token.startswith(')'):
            value = 0.10
        elif re.match(r'^\s{4,}\S', line):
            value = 0.14
        if len(word) == 1:
            value = max(value, 0.24)
        return value

    if low in TITLES or low in INTERJECTIONS:
        return 0.035
    if low in MONEY:
        return 0.95
    if low in MONTHS:
        return 0.95
    if low in STATES and word.istitle():
        value = 1.1
    elif low in CITATIONS:
        value = 1.08 if word[:1].isupper() else 0.76
        if word.isupper():
            value *= 0.65
        if low in {'fig', 'eq', 'figs', 'eqs'}:
            value = 0.64 if low.endswith('s') else 0.44
            if word.isupper():
                value *= 0.6
        if low in {'no', 'nos', 'nr', 'sec', 'pp', 'pg', 'vol', 'cf', 'ed'}:
            value *= 0.65
    elif low in UNITS:
        value = 0.08 if low == 'in' else 0.45
    elif low in {'al', 'v', 'vs'}:
        value = 0.35
    elif len(word) == 1:
        value = 0.24 if word.isupper() else 0.38
    elif word and len(word) <= 7:
        f = frequency(low)
        # Capitalized short forms in prose are often bibliographic truncations.
        if word.istitle():
            english_f = zipf_frequency(low, 'en')
            rarity = max(0., min(1., (5.1 - f) / 1.8))
            if len(word) == 3:
                citation = bool(re.search(r'\d|\bv\.|\bal\.|\(', before))
                value = 1.0 if citation else 0.66
                if english_f >= 5.2:
                    value = 0.08
            else:
                scale = {2: 0.6, 4: 0.75, 5: 0.34}.get(len(word), 0.16)
                value = 0.04 + scale * rarity
        elif word.isupper():
            value = 0.18 if len(word) <= 3 else 0.04
        elif len(word) == 2:
            value = 0.35 * max(0., min(1., (7.0 - f) / 1.4))
        elif len(word) == 3:
            value = 0.24 * max(0., min(1., (5.8 - f) / 1.5))
            if f < 1.5:
                value = -0.025  # unknown identifiers, not natural-language forms
        else:
            value = -0.02
    else:
        value = -0.025
    if len(token) > 1 and token != '.\\':
        value *= 0.6
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    before = '' if new_document else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, before)
    if new_document:
        if token == '.':
            value = 0.12
        elif token == ',':
            value = 0.09
        elif token == '.\n':
            value = -0.62
        else:
            value = -0.33 if token.strip()[:1].isupper() else -0.23
    return (doc, (before + token)[-256:]), float(value)

