"""Layer 1 MLP down-projection, component 4115: a document-opener detector.

It is silent everywhere except on the first token of a document (the first token of a
row, or the first token after a document boundary, where positions restart). There it
responds to the spelling of that token:

- words containing "test" (test, Test, tests, testCase, ...): strongly positive, about 15;
- other words starting with "t" or "T" (Table, Tom, To, Theater, tuning, ...): about 7;
- common function words starting with "th" (the, this, that, they, then, than, ...): 0;
- other tokens: about 1.5 if four or more characters long, otherwise about 0.2.

Non-opening positions give 0. This is a rough summary: a per-token lookup would fit
better, but spelling and length rules capture most of the variance.
"""

READS = ()

FUNCTION_WORDS = {
    "the", "this", "that", "they", "them", "their", "there",
    "these", "those", "then", "than", "though",
}


def step(carry, prefix, upstream):
    opens_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not opens_document:
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    if word in FUNCTION_WORDS:
        value = 0.0
    elif "test" in word:
        value = 15.0
    elif word.startswith("t"):
        value = 7.0
    elif len(word) >= 4:
        value = 1.5
    else:
        value = 0.2
    return carry, value

