"""Approximate a disruption/change detector using words and spelling fragments.

Strong negative responses occur on disrupt/interrupt words, or on prepositions
following changes, faults, harm, or interference. Plural alterations are stronger.
A short text tail also recognizes 'changes were made to'. Some positive responses
mark completion of intra-, anti-, immuno-, and contra- inside split words.
The rules are lexical, not a semantic parse, and miss much of the native activity.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
WORD_GROUPS = {
    'alteration': '''change modification improvement adjustment revision update
        alteration reform enhancement tweak edit''',
    'amendment': 'amendment correction addition extension concession',
    'variation': '''difference variation shift mutation fluctuation pattern trend
        transition transformation''',
    'error': '''error mistake bug flaw typo defect discrepancy inconsistency
        contradiction redundancy vulnerability deficiency weakness gap hole leak''',
    'problem': 'issue problem difficulty trouble complication failure',
    'harm': 'damage harm injury risk threat hazard detriment impairment',
    'effect': 'consequence effect influence impact outcome result',
}
WORD_GROUPS = {name: set(words.split()) for name, words in WORD_GROUPS.items()}

@lru_cache(maxsize=16000)
def group(word):
    forms = set(wordnet.base_forms(word)) | {word}
    for name, words in WORD_GROUPS.items():
        if forms & words:
            return name
    for root in ('disrupt', 'interrupt', 'interfere', 'happen', 'occur'):
        if any(w.startswith(root) for w in forms):
            return root
    if word in {'made', 'done'}:
        return 'made'
    return 'wrong' if word == 'wrong' else 'other'

# Mean responses of the lexical classes; unlisted cases stay near zero.
VALUES = {
    'plural-alteration/to': -5.86,
    'alteration/to': -1.51,
    'amendment/to': -0.48,
    'harm/to': -3.22,
    'effect/to': -0.82,
    'happen/to': -2.36,
    'made/to': -1.26,
    'change-made/to': -6.07,
    'disrupt/to': -6.02,
    'alteration/in': -1.05,
    'variation/in': -0.85,
    'error/in': -2.65,
    'problem/in': -0.38,
    'harm/in': -0.73,
    'happen/in': -1.2,
    'occur/in': -0.61,
    'disrupt/in': -4.95,
    'problem/with': -2.81,
    'error/with': -0.54,
    'interfere/with': -3.36,
    'wrong/with': -5.06,
    'happen/with': -1.92,
    'disrupt/of': -4.06,
    'effect/of': 0.18,
    'alteration/at': -1.53,
    'made/at': -0.9,
    'occur/at': -0.73,
    'as/to': -1.06,
    'as/in': 1.07,
    'disrupt': -5.89,
    'interrupt': -2.65,
    'corrupt': -1.36,
    'prefix-intra': 1.53,
    'prefix-anti': 1.05,
    'prefix-immuno': 0.38,
    'prefix-contra': 0.25,
    'break-root-fragment': -1.52,
    'rupture-root': -1.34,
    'affect': -0.53,
    'happening': -1.0,
}
DEFAULTS = {'to': 0.01, 'in': 0.01, 'with': 0.04, 'of': -0.03,
            'on': 0.03, 'at': -0.07, 'from': -0.10, 'during': 0.06}

