READS = ()
WORDS = re.compile(r"[A-Za-z]+(?:['’][A-Za-z]+)?")

# Infinitive-taking mental states, grouped by their response size.
TO = {word: value for group, value in (
    ('want', -3.60), ('wish', -4.34), ('decide', -3.50),
    ('plan intend', -2.07), ('hope', -1.99), ('seek', -2.22),
    ('eager keen', -2.44), ('ready willing determined', -1.50),
    ('try attempt aim', -0.82), ('need', -0.10),
    ('love prefer desire', -1.40),
) for word in group.split()}
VERBS = set(TO) | {'like', 'look', 'think', 'dream', 'consider', 'contemplate'}
PROGRESSIVE = {
    'looking': -2.89, 'thinking': -2.14, 'considering': -3.63,
    'contemplating': -3.63, 'hoping': -2.72, 'seeking': -1.88,
}
CURRENT = {'looking': -0.58, 'seeking': -1.15,
           'eager': -1.73, 'interested': -0.73}
