    candidates = [word]
    if word.endswith('ing'):
        root = word[:-3]
        candidates += [root, root + 'e']
        if root[-2:-1] == root[-1:]:
            candidates.append(root[:-1])
    if word.endswith('ed'):
        root = word[:-2]
        candidates += [root, root + 'e']
        if root[-2:-1] == root[-1:]:
            candidates.append(root[:-1])
    if word.endswith(('ies', 'ied')):
        candidates.append(word[:-3] + 'y')
    if word.endswith('s'):
        candidates += [word[:-1], word[:-2]]
