    r'(?:quer(?:o|es?|em|emos|er|ia[mn]?|ía[nms]?|ían|íamos)?'
    r'|quier(?:o|es?|en)|quisier(?:a|an)'
    r'|desej(?:o|a|am|amos|ar)|souhait(?:e|es|ez|ent|er|ons)'
    r'|voul(?:ez|ons|oir|ais|ait)|voudr(?:ais|ait|iez|ions)'
    r'|veux|veut|хот(?:ел[аи]?|еть|им|ите|ят)'
    r'|хоч(?:у|ешь|ет|ем|ете|ют)|muốn|ingin|möcht(?:e|en))')
