import re

READS = ()

# Different forms of the same familiar English stem have different strengths.
FORMS = {
    'vary': -7.9,
    'varies': -7.6,
    'varied': -6.4,
    'varying': -4.5,
    'variation': -5.6,
    'variations': -4.0,
    'variability': -2.3,
    'variable': -0.65,
    'variables': -0.1,
    'variety': -0.25,
    'various': -0.13,
    'variance': -0.1,
    'varieties': 0.0,
    'variant': 0.0,
    'variants': 0.0,
}


def activation(token, before, last):
    s = token.strip().lower()
    attached = bool(token and token[0].isalpha() and before)
    word = before + s if attached else s
    spaced = token[:1].isspace()
    # The corresponding Cyrillic spelling also responds at split boundaries.
    if attached and before.endswith('в'):
        if s == 'арь':
            return -14.0
        if s in ('ар', 'ари'):
            return -4.2
    if s == 'вари':
        return -2.0
    if attached and before.endswith(('вар', 'варь')) and s.startswith(('и', 'і')):
        return -3.5
    if s in FORMS:
        value = FORMS[s]
        if (not spaced or token.strip().istitle()) and s in ('vary', 'variation'):
            value *= 1.45
