    if s == 'vari':
        value = -1.3 if token.strip().istitle() else -4.0
        return value if spaced else value * 1.5
    if s == 'var':
        return -2.0 if attached else -0.3
    if s in ('ovarian', 'ovar'):
        return -4.6
    if s == 'ivariate':
        return -2.0
    # A spelling split just before ar/ari/ary is especially salient.
    if attached:
        if before.endswith('v') and s.startswith('ar'):
            if last.lower().strip() == 'bav':
                return -1.8
            if s == 'ary':
                if before.endswith(('ov', 'iv')):
                    return -6.8
                return -15.0 if last.lower() == '-v' else -12.0
            if s == 'ari':
                return -9.0
            if s in ('aria', 'arian'):
                return -7.0
            if s == 'ar':
                return -2.5
            return -1.0
        # Complete familiar inflections and derivatives of the var- stem.
        if before.endswith(('var', 'vari', 'vary')):
            if word.endswith(('variable', 'varied', 'varying', 'variate', 'variar')):
                return -8.5
            if word.endswith(('variation', 'variations')):
                return -7.5
            if s == 'char':
                return -5.1
            if s == 'ability':
                return -4.6
            if word.endswith('varieg'):
                return -6.0
            if s.startswith(('ates', 'iet', 'ier')):
                return -3.2
            if s.startswith(('ance', 'iance', 'iant', 'ious', 'ogram', 'phi', 'theta')):
                return 0.0
            return -1.2
