    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before, last = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = activation(token, before, last)
    word = before + token if token[:1].isalpha() else token
    match = re.search(r'[^\W\d_]+$', word, re.UNICODE)
    tail = match.group()[-24:] if match else ''
    return (doc, tail.lower(), token), value

"""Approximate opening-format responses, plus coarse token-shape averages.

Recognize opening code/markup, escaped tabs, nonbreaking spaces, the numeral
prefix 12, and a posting-date header. Repeated opening formatting keeps its
response. Elsewhere use small spelling-class means; at the first token use
larger case/length/leading-space means. Word-specific and detailed contextual
variation are deliberately left out. Reset all state at document boundaries.
