import regex

READS = ()


def background(token, opening):
    """Coarse spelling/typography averages, not a word lookup."""
    word = token.strip()
    if opening:
        if token.startswith(" "):
            return 0.32 if regex.search(r"\p{Script=Latin}", word) else 0.02
        if len(word) > 11:
            return -0.26
        if word.islower():
            return 0.28 if len(word) <= 4 else 0.08
        if len(word) > 3:
            return 0.15
        return -0.005 if word.isalpha() else 0.055
    if not word.isalpha():
        return -0.0004
    if word.isupper():
        return -0.017
    return -0.0014 if word.endswith("s") else -0.007


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, first, uniform = 0, token, True
        previous = ""
    else:
        _, pos, first, uniform, previous = carry
        uniform = uniform and token == first

    value = background(token, pos == 0)
    if uniform:
        if token == "\r":
            value = 6.67
        elif token == "//\n":
            value = 5.78
        elif token == "<!":
            value = 5.40
