        elif token == "void":
            value = 3.20
        elif token in {"int", "char"}:
            value = 1.48
        elif token == "#ifndef":
            value = 1.20
        elif token == "<|endoftext|>":
            value = 1.46
        elif token == "\\t":
            value = 2.30
        elif token.strip(" \u00a0") == "" and "\u00a0" in token:
            value = 1.72
        elif token == "+\\":
