        value = 3.15
    elif pos == 2 and first == "1" and previous == "2" and token == "2":
        value = 1.14
    elif pos == 1 and first == "Posted" and token == " on":
        value = 2.73
    elif pos == 1 and first == "{" and token == "[":
        value = 1.32

    return (doc, pos + 1, first, uniform, token), value

programs.haiku:
"""Layer-1 MLP output unit 4129: a document-start and repeated-dot detector.

What it does, in plain terms:
- The two-dot token "··" (a run of middle dots) gives a steady response of about +1,
  wherever it sits in a document.
- The first token of a document has no earlier text to look back on, so the unit's
  response there depends on the token alone. Code and markup line openers ("\\r", "//",
  "#", "<!") and rule lines of one repeated symbol ("----", "////", "####") respond strongly;
  lowercase words a little positively; capitalised words, digits and symbols barely;
  newline/tab tokens, chat markers and dotted identifiers a little negatively.
- A document that so far repeats its first token keeps that first-token response.
- A document whose first token is "1" and second token is "2" responds strongly at the "2".
- The word right after a determiner or quantifier ("the", "two", "new", "des") is pushed
  slightly negative. Everywhere else the unit is essentially silent (its mean, about -0.005).
"""

import re

READS: tuple[str, ...] = ()

LINE_OPENERS = {"\r": 6.7, "//\n": 5.8, "//\r\n": 5.6, "<!": 5.4, "#\n": 4.7, "#\r\n": 3.8}
DETERMINERS = {
    " the", " a", " an", " this", " that", " these", " those", " some", " any", " each",
    " every", " no", " all", " both", " most", " many", " several", " other", " another",
    " two", " three", " four", " five", " six", " ten", " one", " single", " multiple",
    " first", " second", " third", " last", " next", " new", " best", " good", " old",
    " existing", " different", " real", " full", " linear",
    " un", " une", " des", " les", " le", " la", " el", " los", " las", " una", " der",
    " die", " das", " den", " del", " eine", " einen", " cette", " ein",
}
RULE_LINE = re.compile(r"(.)\1{2,}")
LOWER_WORD_SPACED = re.compile(r" [a-z]+")
LOWER_WORD = re.compile(r" ?[a-z]+")
CAP_WORD = re.compile(r" ?[A-Z][a-z]+")
REST_VALUE = -0.005
AFTER_DETERMINER = -0.02


def is_two_dots(s):
    return s == "··"


def start_value(s):
    """The unit's response at a document's first token, judged from how the token looks."""
    if s in LINE_OPENERS:
        return LINE_OPENERS[s]
    if is_two_dots(s):
        return 1.0
    if RULE_LINE.fullmatch(s) and not s[0].isalnum() and not s[0].isspace():
        return 1.2
    if s == "<|im_start|>":
        return -0.3
    if s.startswith("."):
        return -0.1
    if any(ord(c) > 127 for c in s):
        return 0.0
    if any(c in "\r\n\t" for c in s):
        return -0.15
    if LOWER_WORD_SPACED.fullmatch(s):
        return 0.3
    if LOWER_WORD.fullmatch(s):
        return 0.2
    if CAP_WORD.fullmatch(s):
        return 0.1
    return 0.05


def step(carry, prefix, upstream):
    """carry = (first token string of this document, whether every token so far equals it,
    number of tokens so far in this document)."""
    s = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        first, uniform, n = s, True, 1
    else:
        first, uniform, n = carry[0], carry[1], carry[2] + 1
        uniform = uniform and s == first
    carry = (first, uniform, n)
    if is_two_dots(s):
        return carry, 1.0
    if n == 2 and first == "1" and s == "2":
        return carry, 3.15
    if n == 1 or uniform:
        return carry, start_value(s)
    if n > 1 and prefix.token_strings[-2] in DETERMINERS:
        return carry, AFTER_DETERMINER
    return carry, REST_VALUE

