"""Approximate a multilingual lexical negation signal.

Emit positive pulses on written negators, negative contraction endings,
and logical !. Adjust English 'not' by its preceding auxiliary, and
use recent function words for language-sensitive no/non/pas/inte.
Chinese 不 is stronger after common verbs (as in 'cannot see').
A few negative spellings are recognized across token boundaries,
even inside identifiers. Everything else gets zero; this is not a
semantic analysis of every possible way to express negation.
"""
import re

READS = ()
NEGATORS = {
    'without': .72, 'cannot': .55, 'neither': .85, 'nothing': .38,
    'none': .4, 'nicht': 1.4, 'ohne': .45,
    'не': 1.8, 'нет': 1., 'não': 1.85, 'nie': 1.5, 'niet': 2.15,
    'nem': 1.1, 'inte': 3.5, 'ikke': 2.3, 'tidak': 1.5,
    'không': 1.15, 'bất': 4.8, 'senza': .9, 'sans': .8,
}
BE_PERFECT_FUTURE = {
    'is', 'was', 'were', 'am', "'s", "'m", "'re", '’s', '’m', '’re',
    'has', 'had', 'will', 'would',
}
NEGATIVE_STEMS = {
    'don', 'doesn', 'didn', 'isn', 'wasn', 'weren', 'aren', 'hadn',
}
SPANISH = {'el', 'la', 'los', 'las', 'que', 'una', 'del', 'y', 'es'}
ITALIAN = {'di', 'che', 'il', 'della', 'gli', 'per', 'una', 'è'}


