    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, text = ('', '') if carry is None or carry[0] != doc else carry[1:]
    word, prev = s.strip().lower(), previous.strip().lower()
    boundary = s[:1].isspace() or not previous[-1:].isalpha()
    value = 0.
    if word == 'not':
        value = 1.65 if s == s.lower() else 1.3
        if not boundary:
            value = 2.4
        if prev in BE_PERFECT_FUTURE:
            value = 2.1
        elif prev in {'are', 'have', 'be', 'been', 'does', 'did', 'should'}:
            value = 1.8
        elif prev in {'do', 'could', 'might'}:
            value = 1.55
        elif prev in {'may', 'must', 'shall', 'and', 'to', 'that'}:
            value = 1.3
        elif prev in {'or', 'maybe'}:
            value = .5
        elif prev in {'if', 'why', 'need', 'for', 'when'}:
            value = .9
            if previous.strip() == 'If':
                value = .15
    elif word in {"'t", '’t', '`t', '‘t'}:
        value = 1.4 if prev in NEGATIVE_STEMS else 1.
        if prev in {'couldn', 'wouldn', 'shouldn'}:
            value = .75
        elif prev in {'hasn', 'haven'}:
            value = 1.15
        elif prev == 'ain':
            value = 2.7
        elif prev == 'n':
            value = 2.2
        elif prev == 'don' and previous.isupper():
            value = 2.8
    elif word == 'nt' and prev in {
        'do', 'does', 'did', 'is', 'was', 'were', 'are', 'could', 'should',
        'would', 'will', 'can', 'have', 'has', 'had', 'must',
    }:
        value = 4.3
    elif word in {'dont', 'doesnt', 'didnt', 'isnt', 'wasnt', 'wont'}:
        value = 1.4 if word == 'dont' else 2.6
    elif word in {'no', 'non'}:
        words = re.findall(r'[^\W\d_]+', text.lower())
        language = SPANISH if word == 'no' else ITALIAN
        value = .7 if word == 'no' else .85
        if len(set(words) & language) >= 2:
            value = 2.1
    elif word == 'inte' and boundary:
        swedish = {'jag', 'du', 'vi', 'det', 'och', 'att', 'som', 'är', 'har'}
        value = 3.7 if set(text.lower().split()) & swedish else .6
    elif word == 'pas' and boundary:
        value = .5 if s.isupper() or s.strip().istitle() else 3.3
        if re.search(r"\bne\b|\bn['’]", text[-80:], re.I):
            value = 4.25
    elif word in NEGATORS and boundary:
        value = NEGATORS[word]
    elif s == '不':
        value = 4.8 if previous and previous[-1] in '，。、；：' else 6.
        # Verb + 不 often expresses inability: 看不... ('cannot see').
        if previous and previous[-1] in '看听聽见見吃喝睡坐走跑说說做拿放抱唤喚':
            value = 8.5
    elif s.endswith('不'):
        value = 4. if word == '不' else 1.5
        if s.startswith(('我', '你', '他', '她', '如果', '为什么')):
            value = 3.4
    elif word in {'没', '沒'}:
        value = 1.15
    elif word == '불':
        value = 4.6
    elif word == 'ไม':
        value = 1.7
    elif s in {'่', '่ม'} and previous.endswith('ไม'):
        value = 11.5 if s == '่' else 4.7
