    elif s.startswith('е') and len(s) > 1 and s != 'ей' and prev == 'н':
        value = 1.35
    elif word.startswith('нед') and boundary:
        value = 1.15
    return (doc, s, (text + s)[-160:]), value

"""A sparse approximation based on opening syntax in code and structured data.

It recognizes assignments to simple names, control-statement parentheses,
quoted dictionary keys, comments, and shell string/heredoc openers. It uses
only the preceding 256 characters and the previous token, resetting at each
new document. Ordinary text and unrecognized syntax default to zero; this
intentionally leaves the component's smaller word-specific responses unexplained.
"""
import re

READS = ()
CONTROL = {'if', 'elif', 'for', 'foreach', 'while', 'switch', 'catch',
           'try', 'synchronized', 'assert'}
MODIFIERS = (r'const|let|var|local|mut|final|static|public|private|protected|'
             r'unsigned|signed')
NAME = r'[A-Za-z_$][\w$]*'
TYPE = r'[A-Za-z_][\w:]*(?:<[^;=]+>)?(?:\[\])?[*&]?'
DECLARATION = rf'(?:(?:{MODIFIERS})\s+)*(?:{TYPE}\s+)?({NAME})'
SHELL_FLAGS = r'\b(sed|grep|awk)(?:\s+-[A-Za-z]+)+$'
INTERPRETER = r'\b(?:python[23]?|node|ruby|perl|php)\s+-[cer]$'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    token = prefix.token_strings[-1]
    word = previous.strip()
    value = 0.0
    line = re.split(r'\n|\\n|;', before)[-1].strip()

    if re.fullmatch(r' ?\(!?[$A-Za-z_]*\s*', token):
        if word in CONTROL:
            strong_headers = {'for', 'foreach', 'try', 'catch', 'switch'}
            value = 1.55 if word in strong_headers else 1.05
            if word == 'for' and re.search(r'[A-Za-z]\s+for$', before):
                value = 0.03  # "solve for (...)" is not a loop
            if '!' in token:
                value *= 0.65
            openers = {'(', '(!', '($', '(int', '(var', '(const', '(let', '(auto'}
            if token.strip() not in openers:
                value *= 0.3  # a fused expression is less responsive
        elif re.search(r'\bfunction$', previous):
            value = 0.90 if '(' in previous else 0.55
    if token in {"('", '("'} and word in {'it', 'test', 'describe', 'context'}:
        value = 0.85  # test declarations open a descriptive string

    if token in {' =', '='}:
        lhs = re.sub(r'^[-+ ]*\d+\t\s*', '', line)
        lhs = re.sub(r'^(?:```\w*|//|#)\s*', '', lhs)
        lhs = lhs.rsplit(': ', 1)[-1].rsplit('{', 1)[-1].strip(' +-')
