        if match:
            value = 0.70 if len(match[1]) > 1 else 0.48
        elif re.search(r'\bfor\s*\(\s*(?:\w+\s+)*\w+$', lhs):
            value = 0.65
        elif token == ' =':
            value = -0.025
        if token == '=':
            value *= 0.30  # no leading space: a much weaker assignment response
    if token in {' :=', ' <-'}:
        value = 0.72 if token == ' :=' else 1.0

    # A comma inside an object can be followed by a new quoted key.
    object_context = before.rfind('{') > max(before.rfind('['), before.rfind('('))
    if token in {' "', " '", ' \\"', ' "\n'}:
        escaped = '\\' in token
        value = 0.20 if escaped else -0.04
        if previous.rstrip().endswith(',') and object_context:
            value = 0.65 if escaped else 1.05
            if re.search(r'"name"\s*:\s*"[^"\n]*",$', before):
                value = 1.35
