            value = 0.42 if '\t' not in previous else 0.22
        if word == 'case' and token == " '":
            value = -0.66
        elif word in {'==', '!=', '!==', '<', '>'}:
            value = -0.25
        if word == 'echo':
            value = 0.30
        command = re.search(SHELL_FLAGS, before)
        if command:
            value = 1.70 if command[1] == 'sed' else 0.95
        elif re.search(INTERPRETER, before):
            value = 1.12
        elif before.rstrip().endswith('<<'):
            value = 0.58

