        value = 0.50 if token == '//' else 0.02
        if previous.isspace() and '\n' not in previous:
            value = 0.57
        elif '\n' in previous:
            value = 0.40 if token == '//' else 0.25
        elif previous in {'\\n', '\\t'}:
            value = 0.74
    if token == '//\n' and not before:
        value = 3.82  # an opening comment line at the document boundary
    if token in {'#', ' #'}:
