programs.haiku:
"""layers.1.mlp.down_proj:4131 -- a "code punctuation" component.

What it does: it is nearly silent on most text, and fires on a few code-syntax tokens:
  * an opening "(" right after a control keyword (`for (`, `if (`, `catch (`, `while (`),
    strongest (~1.2);
  * "=" in a declaration line (`const x =`, `var x =`, `int x =`, `let x =`), ~0.7; a
    plain "=" after a name (`x = ...`) gives ~0.3, and "=" after ")" or "]" gives 0;
  * Go-style ":=" (~0.7);
  * comment starters "//" and "#" (~0.4);
  * a double quote that opens a string right after a comma, colon, brace, bracket,
    or whitespace (e.g. the quoted keys of JSON-like tool calls), ~0.5;
  * an escaped quote \\" (~0.3).
Everything else is predicted as 0. The values are the mean activation of each group
measured on training text.

Main idea: the activation is large and positive at the token where code is about to
start a new name, value or loop header, and near zero elsewhere.
"""

READS = ()

CONTROL = {"for", "if", "catch", "while", "switch"}
DECL = {"var", "const", "let", "int", "final", "String", "double", "float", "long",
        "char", "bool", "private", "public", "protected", "static", "val", "auto"}
COMMENT = {"//", "#"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip()
    prev = toks[-2].strip() if len(toks) > 1 else ""
    # carry = the first non-blank token of the current line
    if "\n" in toks[-1]:
        line = ""
    elif carry in (None, "") and cur:
        line = cur
    else:
        line = carry
    if cur == "(" and prev in CONTROL:
        return line, 1.2
    if cur in COMMENT:
        return line, 0.4
    if cur == "=":
        if line in DECL:
            return line, 0.7
        if prev.isidentifier():
            return line, 0.3
        return line, 0.0
    if cur == ":=":
        return line, 0.7
    if cur == '"' and (prev == "" or prev in ('",', ":", "{", "[", ",", "(")):
        return line, 0.5
    if cur == '\\"':
        return line, 0.3
    return line, 0.0

programs.sol:
"""Local phrase and code-convention detector, with zero elsewhere.

Negative responses concentrate on noun-like 'use', especially 'for use' and
'in use'; 'in full' and 'purposes' have smaller negative responses. Positive
responses include 'custom', documentation tags and warning annotations.
Special cases recognize literal test/diff headers and document openings.
Only the last two tokens and document-initial formatting are remembered.
"""
from functools import lru_cache
import wordnet

READS = ()

DOCUMENTATION = {
    'file': 7.2,
    'brief': 5.1,
    'see': 3.7,
    'link': 1.3,
    'var': 1.3,
}
ANNOTATIONS = {
    'SuppressWarnings': 5.7,
    'BindView': 3.0,
}


@lru_cache(maxsize=2048)
def adjective(word):
    return ('adjective' in wordnet.parts_of_speech(word)
            and word not in {'only', 'even', 'still', 'just', 'also', 'all'})


def predict(token, previous, before, position, pure_cr):
    word = token.strip()
    prev = previous.strip().lower()

    # 'Use' in prose, identifiers, imports and hyphenated compounds.
    if word.lower() == 'use' or word in {'.use', '_use', '-use', '/use'}:
        if word in {'.use', '_use', '-use', '/use'}:
            return -1.9
        if word == 'USE':
            return -1.4
