"""Layer-1 MLP down-projection component 4132.

It is mostly a lexical detector with two sides:
- The word "use" drives it strongly negative when it is a noun after a preposition
  ("for use", "in use", "of use", "daily use"), about -5.5. "in full" is about -3.5.
  "use" in code-like spots is mildly negative; the verb after "to/can/we/you" is ~0.
- Javadoc/Doxygen tags written right after "@" or a backslash are positive:
  "brief" ~5, "see" ~3.4, "link" ~1.7, "Override" ~1.4, "return" and "param" small.
Everything else is predicted as 0.
"""
READS = ()

NOUN_PREV = {"for", "in", "of", "from", "daily", "single"}
CODE_PREV = {"(", '"', "+", "=", "   ", "'", ":", "\n"}
VERB_PREV = {"to", "can", "we", "you", "will", "may", "i", "they", "should", "just", "also"}
TAGS = {"brief": 5.0, "see": 3.4, "link": 1.7, "Override": 1.4, "return": 0.3, "param": 0.2}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    raw = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    p = prev.strip().lower()
    if word.lower() == "use":
        if p in NOUN_PREV:
            return carry, -5.5
        if p in VERB_PREV:
            return carry, 0.0
        if prev[-1:] in CODE_PREV or p in CODE_PREV:
            return carry, -1.5
        return carry, -0.5
    if word.lower() == "full" and p == "in":
        return carry, -3.5
    if prev.endswith(("@", "\\")) and word in TAGS:
        return carry, TAGS[word]
    return carry, 0.0

