        elif s[0].isupper():
            value = 0.25
        elif low == 'name':
            value = 0.55 if token[0].isspace() else 0.30
            if '<tool_call>' in history and history.endswith('{"'):
                value = 0.55
            if history.lower().rstrip().endswith('given'):
                value = 1.95
        else:
            value = {'names': 0.63, 'named': 0.35, 'naming': 1.2}[low]
    elif low in ('имя', '이름', 'danh'):
