"""Estimate a within-token length feature, not the length of a whole word.

Long Latin words/identifiers and four-or-more East Asian letters fire.
Capitalization and unspaced word pieces strengthen the response. Long
spacing and separator runs also fire, but indentation is much weaker.
Chat-control markers are excluded. Equal-length words still differ in the
real component; this program deliberately does not memorize those words.
"""
from functools import lru_cache
import unicodedata

READS = ()
CHAT_TAGS = {
    '<think>', '</think>', '<tool_call>', '</tool_call>',
    '<tool_response>', '</tool_response>',
}


@lru_cache(maxsize=32768)
def token_value(text, indentation):
    if text.startswith('<|') or text in CHAT_TAGS:
        return 0.0
    if text.isspace():
        n = len(text.replace('\n', '').replace('\r', ''))
        if '\n' in text:
            return max(0.0, 0.06 * (n - 4))
        if indentation:
            return max(0.0, 0.025 * (n - 4))
        if n <= 12:
            return max(-0.03, 0.075 * (n - 4))
        return min(4.3, 0.6 + 0.55 * (n - 12))
    letters = ''.join(c for c in text if c.isalpha())
    n = len(letters)
    wide = sum(unicodedata.east_asian_width(c) in ('W', 'F')
               for c in letters)
    if wide:
        return 1.7 + 0.1 * (wide - 4) if wide >= 4 else -0.015
    if n:
        if not letters.isascii():
            return min(0.8, max(0.0, 0.2 * (n - 7)))
        if n <= 7:
            return -0.008
        camel = any(a.islower() and b.isupper()
                    for a, b in zip(letters, letters[1:]))
        if camel:
            return min(2.5, 0.4 * (n - 8))
        if letters.istitle() or letters.isupper():
            return min(0.8, max(0.04, 0.4 * (n - 8)))
        if not text.startswith(' '):
            return min(1.0, max(0.07, 0.5 * (n - 8)))
        return -0.05 if n == 8 else min(0.42, 0.16 * (n - 8.3))
    # Long repeated punctuation is a visual separator rather than a word.
    n = len(text.strip())
    if n >= 6 and len(set(text.strip())) <= 2:
        return min(3.5, max(0.0, 0.3 * (n - 7)))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    indentation = bool(previous and previous.rstrip(' \t').endswith('\n'))
    value = token_value(text, indentation)
    if not previous and text.isalpha():
        value -= 0.18
    return (doc, text), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:4149 -- a "long token" detector.

The component fires on tokens that are long in their own writing system:

  * long runs of one repeated character (spaces, tabs, or a symbol such as - = _ *):
    code indentation and separator lines like "----------------". A long run in the
    middle of a line fires hard; a run that starts a line (indentation after a newline)
    fires less;
  * long words (9+ letters), e.g. "information", "workspace", "University", also when
    glued to code punctuation, as in ".springframework", "/workspace", "_description".
    ALL-CAPS, capitalised and code-style forms fire harder than ordinary lowercase words;
  * camelCase identifiers, e.g. "addCriterion";
  * Chinese or Japanese words of four or more characters, e.g. "应用程序", "有限公司";
  * a long run of spaces followed by a newline.

Everything else (function words, punctuation, digits, short words) predicts 0.
"""

READS = ()

RUN_MIN, MID_MIN = 16, 8
LONG_WORD = 9
CODE_PREFIX = "./_(\t"


def _run_length(s):
    """Length of the run of one repeated character that the token is (leading spaces
    count), or 0. A whitespace-only token counts as a run of its length."""
    if s.strip(" \t") == "":
        return len(s)
    body = s.lstrip(" ")
    if body[0] not in "\r\n" and body == body[0] * len(body):
        return len(s)
    return 0


def _is_camel(core):
    return core.isascii() and core.isalnum() and any(
        a.islower() and b.isupper() for a, b in zip(core, core[1:])
    )


def _is_cjk_word(core):
    return len(core) >= 4 and all(
        "぀" <= c <= "ヿ" or "一" <= c <= "鿿" for c in core
    )


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    core = s.strip(" ")
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    word = core.lstrip(CODE_PREFIX)
    run = _run_length(s)
    if run >= RUN_MIN:
        # long run: strong mid-line, weaker as line-start indentation
        if s.strip(" \t") == "" and "\n" in before:
            value = 1.0                  # indentation at the start of a line
        else:
            value = 3.5
    elif run >= MID_MIN:
        value = 0.5                      # shorter separator or indentation run
    elif s.strip(" \t") == "\n" and len(s) >= RUN_MIN:
        value = 1.5                      # long indentation then a newline
    elif word.isascii() and word.isalpha() and len(word) >= LONG_WORD:
        if word.isupper():
            value = 1.4                  # ALL-CAPS word, e.g. WARRANTIES
        elif s[0] in CODE_PREFIX:
            value = 1.3                  # code-style: .name, /path, _name, (name
        elif word[0].isupper() or not s.startswith(" "):
            value = 0.7                  # capitalised word
        else:
            value = 0.3                  # ordinary lowercase long word
    elif _is_camel(core):
        value = 0.7                      # camelCase identifier
    elif _is_cjk_word(core):
        value = 2.0                      # Chinese or Japanese word of 4+ characters
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Local cues for the start of a question, especially auxiliary--subject order.

Spanish's inverted question mark is the strongest cue.  English auxiliaries
have a smaller response at question openings, followed by a larger response
on 'you'.  A preceding wh-word changes that response substantially; 'how can
you' is negative, unlike 'can you'.  Other subjects give smaller responses.
Arabic, Polish and Chinese question expressions are additional cues.  The
program also distinguishes object-like uses of "you" and scores "you think"
and "you mean" continuations.  History resets at document boundaries.  Most
background activations and unrelated multilingual effects are left at zero.
"""
import re

READS = ()

# Ordinary English auxiliary verbs, weighted at a question opening.
OPENING = {
    'am': 0.6, 'is': 0.8, 'are': 0.75, 'was': 0.6, 'were': 0.6,
    'do': 0.7, 'does': 0.85, 'did': 0.75,
    'can': 0.4, 'could': 0.3, 'will': 0.5, 'would': 0.45,
    'shall': 0.4, 'should': 0.35, 'may': 0.3, 'might': 0.3,
    'must': 0.3, 'have': 0.5, 'has': 0.5, 'had': 0.4,
}
YOU = {
    'are': 4.0, 'was': 1.0, 'were': 0.9,
    'do': 6.6, 'did': 2.3,
    'can': 5.4, 'could': 2.8, 'will': 1.2, 'would': 4.5,
    'shall': 0.5, 'should': -1.3, 'may': 0.4, 'might': 0.0,
    'must': 0.0, 'have': 3.6, 'had': 0.8,
}
WH = set('what how why where when who whom whose which'.split())
SUBJECTS = set('i we he she it they there this that these those'.split())
DETERMINERS = set('the a an your my our his her their its'.split())
CONJUNCTIONS = set('and or but nor so then'.split())


def recent_question_word(history):
    """Look only within the latest short clause, not across sentences."""
    text = ''.join(history[-8:])
    text = re.split(r'[.!?;\n]', text)[-1]
    words = re.findall(r'[a-z]+', text.lower())
    return next(((w, len(words) - i - 1)
                 for i, w in reversed(list(enumerate(words))) if w in WH),
                ('', 0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    previous = history[-1] if history else ''
    p = previous.strip().lower()
    q, distance = recent_question_word(history[:-1])
    if previous.strip().istitle() and distance:
        q = ''
    value = 0.0

    if '¿' in s:
        value = 13.5 if history else 9.3
    # Arabic yes/no-question particle, not a fragment inside another word.
    elif w == 'هل' and (s[0].isspace() or not history):
        value = 6.2
    elif w == 'czy':  # Polish yes/no-question particle (also 'whether').
        value = 1.5
    elif w == 'zy' and p == 'c':  # Initial letters of Polish 'czy'.
        value = 3.7
    elif w in {'请问', '請問'} or (w == '問' and p == '請'):
        value = 3.0
    elif w in {'你觉得', '你覺得'}:
        value = 4.5
    elif w in {'难道', '難道'}:
        value = 3.3
    elif w == 'you':
        if p in YOU:
            value = YOU[p]
            if previous.strip().islower() and not q:
                value -= {'do': 2.4, 'can': 1.6, 'are': 1.5,
                          'have': 1.9, 'would': 0.6, 'could': 1.2}.get(p, 0.0)
            if q:
                if p in {'can', 'could'}:
                    value = -4.3 if q == 'how' else -2.0
                    if distance:
                        value *= 0.5
                elif p == 'do':
                    value = {'what': 2.2, 'how': 0.15, 'why': 0.5}.get(q, 1.3)
                elif p == 'are':
                    value = 2.0 if q == 'what' else 0.8
                elif p == 'did':
                    value = {'what': 1.7, 'how': 0.3, 'why': 0.3}.get(q, 0.8)
                elif p == 'have':
                    value = 1.0
                elif p == 'would':
                    value = 1.5 if q == 'what' else 0.0
                elif p == 'will':
                    value = -0.5
        elif p in {"'t", '’t'} or p.endswith("n't") or p.endswith('n’t'):
            value = 1.1
        elif p in {'tell', 'tells', 'told'}:
            value = -1.6 if p == 'tell' else -0.8
        elif p in {'want', 'wants', 'ask', 'asks'}:
            value = -0.6
        elif p == 'what':
            value = -2.2 if previous.strip().istitle() else -0.45
        elif p == 'how':
            value = -0.3
        elif s.strip() == 'You' or p in {',', '.'}:
            value = -0.2
    elif p in OPENING and w in SUBJECTS | DETERMINERS:
        if p == 'do' and w in {'it', 'this', 'that'}:
            value = -0.05  # Usually an object: 'do it', not a subject.
        elif w == 'that' and (not carry or carry[2] <= 0.1):
            value = 0.0  # Declarative 'the point is that ...'.
        elif w in DETERMINERS:
            value = 0.2 if carry and carry[2] > 0.1 else 0.0
        else:
            value = 0.85
            if w == 'i' and p == 'do':
                value = 1.1
            elif w == 'we' and p in {'do', 'are', 'have'}:
                value = 1.3
            elif w == 'it' and p in {'is', 'was', 'would'}:
                value = 1.1
            elif w == 'there':
                value = 0.7 if p == 'is' else 0.3
            if q:
                value *= 0.65
    elif w in OPENING:
        base = OPENING[w]
        if p in WH:
            if p in {'who', 'which'} and w not in {'do', 'does', 'did'}:
                value = 0.0
            elif w in {'is', 'are', 'was', 'has'} and p == 'what':
                value = 0.15
            elif w == 'do':
                value = 1.05
            elif w == 'does':
                value = 0.85
            elif w in {'can', 'could'}:
                value = 0.2 if p == 'how' else 0.45
            else:
                value = base
        elif s.strip().istitle() and history:
            value = base
        elif any(c in previous for c in ',?!:;'):
            value = 0.7 * base
        elif p in CONJUNCTIONS:
            value = 0.0 if previous == ' and' else 0.65 * base
        elif q and w in {'do', 'does', 'did'}:
            value = 0.5
        elif w == 'does':
            value = 0.1
    elif p == 'you' and w in {'think', 'mean'}:
        earlier = history[-2].strip().lower() if len(history) > 1 else ''
        negated = earlier.endswith("n't") or earlier in {"'t", '’t'}
        if earlier in OPENING or negated:
            value = 2.4 if w == 'think' else 4.0
            if len(history) > 2 and history[-3].strip().lower() in WH:
                value *= 0.45
        elif w == 'mean':
            value = 2.5
    elif p == 'i' and w == 'think':
        value = -0.2

    return (doc, (*history[-9:], s), value), float(value)

"""Estimate a GET-spelling response, modulated by prose versus code.

Get/got/getting are negative in prose; negation strengthens the estimate,
while perfect contractions and mathematical context can soften it. Code
syntax weakens the prose response, and accessor names are positive. Git
and split g-vowel-t spellings also respond. Everything else is zero.
The short text buffer resets between documents.
"""
import re

READS = ()
FORMS = {'get': -4.2, 'gets': -5.1, 'getting': -6.0,
         'got': -5.6, 'gotten': -6.0, 'getter': -1.8, 'getters': -1.8}
DECLARATION = r'\b(?:public|private|protected|def|func|function|const|void|var)\b'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    joined = tail.replace('\\n', '\n').replace('\\t', '\t')
    words = re.findall(r'[a-z]+', joined.lower())
    last = words[-1] if words else ''
    math = bool(re.search(r'\$|\\(?:frac|sum|sqrt)|\b(?:equation|multiply|'
                          r'substitute|matrix|hence|thus|simplify)\b', tail, re.I))
    value = 0.0
    if word in {'GET', '_GET', '.GET'}:
        value = -1.5
    elif re.match(r'^\.?[gG]et[A-Z_]', word):
        value = 1.8 if 'get' in word else 0.7
    elif word in {'.get', '.Get'} or (lower == 'get' and
            not token[:1].isspace() and tail.endswith(('.', '->'))):
        value = 0.45 if word == '.Get' else 1.5
        if last == 'self':
            value = -0.2
        if tail.endswith('->'):
            value = 2.2
    elif lower in {'git', '.git', '_git'}:
        value = -4.25 if lower.startswith('.') else -2.8
    elif lower in FORMS:
        value = FORMS[lower]
        if lower == 'get':
            recent = joined[-120:]
            declaration = bool(re.search(DECLARATION, recent))
            syntax = sum((';' in recent, bool(re.search(r'[{}]', recent)),
                          bool(re.search(r'\w\(', recent)), '=' in recent))
            indent = bool(re.search(r'\n[ \t]{3,}[^\n]*$', joined))
            value += (0.8 * syntax + 2.1 * declaration + 1.2 * indent
                      + 0.8 * ('\n' in joined[-15:]) + 0.5 * math
                      - 0.9 * (last == 'to')
                      - 1.9 * (last in {'t', 'not', 'cant', 'cannot',
                                        'couldnt', 'didnt'}))
            if declaration and re.search(r'[>\]]\s*$|\b[A-Z]\w*\s*$', joined):
                value = max(value, 1.5)
            if word == 'Get':
                value = -1.2 if syntax or declaration else -4.1
            if word == lower and not token[:1].isspace():
                if tail[-1:].isalpha():
                    value = -1.8
                if tail.endswith(('`', '"', "'", '_')):
                    value = -0.7
                if tail.endswith('::'):
                    value = 0.3
        elif lower == 'got':
            if re.search(r"['’]ve$", tail):
                value += 3.9
            elif re.search(r"['’]s$", tail):
                value += 2.6
            value += 0.7 * math
        elif lower == 'getting':
            value += 1.2 * (last in {'is', 'am', 'are'}) + math
        elif lower == 'gets':
            value = -1.1 if word == 'Gets' else value + 1.4 * math
    elif re.match(r'^[(</-]get$', word):
        value = -1.2
    elif not token[:1].isspace():
        if tail.lower().endswith('get') and lower == 'ting':
            value = -6.5
        elif tail[-1:].lower() == 'g' and re.match(r'^[aeioö]t', lower):
            if len(lower) == 2:
                value = {'a': -6.1, 'e': -5.0, 'i': -2.8,
                         'o': -8.6, 'ö': -3.8}[lower[0]]
            else:
                value = -3.8 if lower.startswith('ot') else -1.0
    return (doc, (tail + token)[-240:]), float(value)

programs.haiku:
"""Spelling of the 'if' syllable inside a word (identify, verify, classification,
significant, the Russian -ифи- and Italian -ific- forms).

The component fires on the -if- / -ify / -ific / -ification / -ified morpheme of
Latinate verbs and nouns. It is strongest when that morpheme is glued onto the
end of a word piece (Fast|ify, sapon|ification), weaker when the token starts a
word (' identify'), and near zero on the conditional word 'if' and on words that
merely contain the letters (life, shift, different). Pieces that continue a word
after an 'if' piece (identi|fi|ed) get a weak value. Runs of middle dots and the
first token of each row have small, fixed negative values.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.lower().strip()
    glued = not raw.startswith(" ")
    if prefix.position == 0:
        return carry, -0.3  # first token of a row
    if raw and set(raw) == {"·"}:
        return carry, -0.6  # run of middle-dot leaders
    if "ﬁ" in s:
        return carry, 4.0  # fi ligature
    if "signific" in s:
        return carry, 1.7  # significant, significance
    if "ific" in s or "ify" in s or "ifi" in s:
        return carry, 2.0 if glued else 0.4  # identify, classification, verified
    if s == "if":
        return carry, 0.4 if glued else 0.1  # the conditional word 'if'
    if "иф" in s or "фик" in s or "ифи" in s:
        return carry, 3.0  # Russian -ифи- spelling
    if "ци" in s:
        return carry, 0.4  # Russian -ци- after -ифи-
    if glued and "if" in s:
        return carry, 0.1
    # continuation piece of a word whose previous piece had the 'if' spelling
    if glued and prefix.position > 0:
        back = prefix.token_strings[-2].lower()
        if "if" in back and " " not in back and prefix.token_strings[-2][:1] != " ":
            return carry, 0.3
    return carry, 0.0

programs.sol:
"""A spelling-sensitive average/avg response, with an opposite verb/VB response.

Average words are strongly positive, especially when a token completes a
split spelling. Short v-g fragments share this response; v-b fragments have
the opposite sign. Longer continuations are weaker than single letters.
Ave and Chinese 平均 get smaller positive responses; VF is negative.
The 'of' immediately after average has a small positive after-response.
Unmatched text gets zero. Only the same-document predecessor is retained.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    prev = previous.lower()
    value = 0.0

    if word in ('average', 'averages', 'averaged', 'averaging'):
        value = 6.3 if word in ('averaged', 'averaging') else 4.9
        if word == 'averages':
            value = 5.5
    elif word in ('avg', 'vg'):
        value = 4.5
    elif word == 'verg':
        value = 2.9
    elif word == 'aver':
        value = 2.5
    elif word in ('verb', 'verbs', 'vb'):
        value = -3.5
        if word == 'vb' and '```' in previous:
            value = -7.0
    elif word == 'vf' and token[:1].isspace():
        value = -1.8
    elif token.strip() == 'Ave':
        value = 1.9
    elif word == '平均':
        value = 2.4
    elif word == 'of' and prev.strip() in ('average', 'averages'):
        value = 1.1

    if previous and not token[:1].isspace():
        joined = prev + word
        start = joined.find('averag')
        if 0 <= start < len(prev) < start + 6:
            value = 10.0
        elif prev.endswith(('v', 'ver')):
            if word.startswith('g'):
                value = 5.0 if len(word) == 1 else 2.0
            elif word.startswith('b'):
                value = -1.5 if len(word) == 1 else -2.5
    return (doc, token), value

"""Approximate a pre-noun modifier signal, not an adjective's meaning.

English adjectives and participles have a negative response, especially in a
noun phrase opened by a determiner or quantity. Predicate adjectives are much
weaker. WordNet supplies lexical classes; word length and ordinary adjective
endings estimate the strength. For words that are also nouns, frequent
plurals reduce the modifier response; indefinite articles strengthen clear
adjectives. Separate spaces in that slot often start a
numeric modifier. Document starts have a small positive response.
"""
import re
from functools import lru_cache
import wordnet
import wordfreq
import inflect

_INFLECT = inflect.engine()

READS = ()
DETERMINERS = set('a an the this that these those my your his her its our their '
                   'whose each every any some no another such what which'.split())
QUANTITIES = set('all both several many few more most less much enough other '
                 'one two three four five six seven eight nine ten eleven '
                 'twelve hundred thousand million billion'.split())
COPULAS = set('is are was were be been being seem seems seemed become becomes '
              'became feel feels felt look looks looked remain remains'.split())
PRONOUNS = set('i you he she it we they me him them us who'.split())
DEGREE = set('very quite rather too so extremely highly relatively increasingly '
             'particularly especially fully well slightly somewhat not more '
             'most less least nearly almost really fairly completely'.split())
PREPOSITIONS = set('of in on at by for from with without as into over under '
                    'between through within against during'.split())
ENDINGS = ('al', 'ic', 'ical', 'ive', 'ous', 'ful', 'less', 'able', 'ible',
           'ary', 'ory', 'istic')

@lru_cache(maxsize=50000)
def parts(word):
    return wordnet.parts_of_speech(word) if word.isascii() else frozenset()


@lru_cache(maxsize=10000)
def plural_rarity(word):
    """A common plural suggests a genuine count-noun use, not just an adjective."""
    plural = _INFLECT.plural_noun(word)
    gap = (wordfreq.zipf_frequency(word, 'en')
           - wordfreq.zipf_frequency(plural or '', 'en'))
    return max(0.0, min(3.0, gap))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', '', 0, 0)
    _, position, word, previous, last, noun_slot, predicate = carry
    continuing = bool(word and s and s[0].isascii() and s[0].isalpha()
                      and last and last[-1].isalpha())
    if not continuing:
        if word:
            previous = word.lower()
        word = ''
        if previous in DETERMINERS or previous in QUANTITIES:
            noun_slot, predicate = 3, 0
        elif previous in COPULAS or previous in PRONOUNS or previous == 'to':
            noun_slot, predicate = 0, 3
        elif (previous in DEGREE or previous in {'and', 'or'}
              or last.strip() in {',', '-'} or 'adjective' in parts(previous)):
            noun_slot, predicate = max(0, noun_slot-1), max(0, predicate-1)
        else:
            noun_slot, predicate = 0, 0
    tail = re.search(r'[A-Za-z]+$', s)
    if tail:
        word += tail.group()
    elif s.strip():
        word = ''
    if any(ch in s for ch in '.;!?\n'):
        noun_slot, predicate = 0, 0
    w = word.lower()
    p = parts(w)
    adjective = 'adjective' in p
    noun = 'noun' in p
    pure_adjective = adjective and not (p & {'noun', 'verb', 'adverb'})
    suffix = len(w) > 4 and w.endswith(ENDINGS)
    participle = len(w) > 4 and w.endswith(('ed', 'ing'))

    value = 0.001
    if position == 0:
        value = 0.30
    elif pure_adjective:
        if noun_slot:
            value = -(0.08 + 0.055 * min(len(w), 12))
            if previous in {'a', 'an'}:
                value -= 0.12
        elif predicate:
            value = 0.01
        elif previous in PREPOSITIONS:
            value = -0.28 if len(w) > 4 else -0.06
        else:
            value = -0.32 if len(w) > 7 else (-0.10 if len(w) > 5 else 0.0)
    elif noun_slot:
        if s and not s.strip():
            value = -0.35
        elif adjective:
            if noun:
                value = -0.01 - 0.09 * plural_rarity(w)
            else:
                value = -0.36 if len(w) < 8 else -0.60
        elif participle and not noun:
            value = -0.35
        elif s.startswith('-'):
            value = -0.22
    elif adjective and suffix:
        value = -0.22 if previous in PREPOSITIONS else -0.08
    elif w in QUANTITIES and 'adverb' not in p:
        value = -0.09
    return (doc, position+1, word, previous, s, noun_slot, predicate), value

"""A sparse approximation of the component's strongest lexical spellings.

Respond to locale identifiers and the -ale/-ore words rationale, finale,
flare and lore. Most other fragments are left at zero because their response
varies strongly with the surrounding name and language. Also recognize a few
negative document-opening markers. This is only a partial explanation.
"""
import re
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    text = '' if start else carry[1]
    token = prefix.token_strings[-1]
    before = text
    text = (text + token)[-160:]
    match = re.search(r'[^\W\d_]+\Z', text)
    word = match.group().lower() if match else ''
    value = 0.0
    if token == '.Locale':
        value = 12.0
    elif token == 'Locale':
        value = 10.5
    elif token in ('/locale', 'locales'):
        value = 7.0
    elif token.strip() in ('locale', 'locales') and re.search(
        r'\b(const|let|var|return|set)\s*$', before
    ):
        value = 9.0
    elif word == 'rationale' and len(token.strip()) >= 2:
        value = 8.7 if token == 'ALE' else 3.8
    elif token.strip().lower() in ('finale', 'flare'):
        value = 1.8
    elif token.strip().lower() == 'lore' and (
        word == 'lore' or word.endswith('folklore')
    ):
        value = 2.8
    elif text == 'Title:':
        value = -4.47
    elif start and token == '//\n':
        value = -6.2
    elif token == '\r' and not text.strip('\r'):
        value = -4.0
    elif token and not token.strip('·') and not text.strip('·'):
        value = -2.05
    return (doc, text), value

"""A local collection-and-contents feature.

Negative at links naming a collection's members ("set of"), definite
contents ("contains the", "return all"), and descriptions of storing or
returning data. Coefficients are shared by semantic classes. A short text
tail supplies the previous word, comment markers, and mathematical notation;
it is cleared at document boundaries. Parameter/result links can be positive.
A separate offset marks tool-response opening tags. This is an approximation,
not a parser; many token-specific and broader-context effects are omitted.
"""
import re

READS = ()

COLLECTIONS = set(
    "array list tuple vector matrix grid set collection sequence dictionary "
    "dict stack queue heap table slice ensemble".split()
)
AGGREGATES = set(
    "sum union intersection series group category class space subspace range "
    "graph family system language".split()
)

CONTAINMENT = set('contain hold'.split())
INCLUSION = set('include comprise consist'.split())
STORAGE = set('store save keep'.split())
TRANSFER = set('pass send receive give provide supply deliver'.split())
RETURN = set('return'.split())
ACCESS = set('get obtain retrieve extract fetch'.split())
OUTPUT = set('print display show output emit'.split())
EDIT = set(
    'add remove subtract insert append concatenate sort process parse '
    'read load generate create'.split()
)

# Verb class, response on 'the/all/only', extra response on 'all/only'.
OBJECT_VERBS = [
    (CONTAINMENT, -0.79, -0.3),
    (INCLUSION, -0.17, -0.44),
    (STORAGE, -0.45, -0.18),
    (TRANSFER, -0.33, -0.07),
    (RETURN, -1.45, 0.21),
    (ACCESS, -0.54, -0.21),
    (OUTPUT, -0.41, -0.27),
    (EDIT, -0.42, -0.36),
]
VERBS = set().union(*(group for group, _, _ in OBJECT_VERBS)) | {'use'}
# Current-verb response: base, inflection, preceding modal/relative link.
DIRECT_VERBS = [
    (CONTAINMENT, (0.0, -0.22, -0.4)),
    (STORAGE, (0.06, -0.15, -0.21)),
    (RETURN, (0.0, -0.32, -0.85)),
]


def verb_root(word):
    word = word.lower()
    word = {'gave': 'give', 'given': 'give', 'held': 'hold',
            'kept': 'keep', 'got': 'get', 'sent': 'send'}.get(word, word)
    if word in VERBS:
        return word
    for ending in ('ing', 'ed', 's'):
        if word.endswith(ending):
            root = word[:-len(ending)]
            undoubled = root[:-1] if root[-1:] == root[-2:-1] else root
            for candidate in (root, root + 'e', undoubled):
                if candidate in VERBS:
                    return candidate
    return word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    words = re.findall(r'[A-Za-z]+', tail)
    previous = words[-1].lower() if words else ''
    before = words[-2].lower() if len(words) > 1 else ''
    if previous.endswith('s') and previous[:-1] in COLLECTIONS:
        previous = previous[:-1]
    root = verb_root(previous)
    word = text.strip().lstrip('.')
    value = 0.003

    if word == 'of':
        if previous in COLLECTIONS:
            value -= 1.23
            if before in ('the', 'an', 'any'):
                value -= 1.22
            if '$' in tail or '\\(' in tail or '\\[' in tail:
                value -= 0.67
            if previous in ('array', 'list', 'tuple'):
                value -= 0.16
        if previous in AGGREGATES:
            value -= 0.45
        if previous in ('product', 'ring', 'algebra', 'polynomial'):
            value -= 2.11
        if previous in ('parameter', 'argument'):
            value += 1.85
        if previous in ('result', 'state'):
            value += 0.37
        if root == 'consist':
            value -= 0.68

    if word in ('the', 'all', 'only'):
        value += {'the': 0.0, 'all': -0.11,
                  'only': -0.14}[word]
        for group, response, quantified in OBJECT_VERBS:
            if root in group:
                value += response
                if word != 'the':
                    value += quantified
        if word != 'the':
            value += {'of': -0.75,
                      'over': -1.45,
                      'with': -0.33}.get(previous, 0.)
        if previous in ('only', 'just'):
            value -= 0.52
        if word == 'the' and root == 'use':
            value -= 0.3

    # Current verbs: base, inflected form, and a preceding modal/relative link.
    current_root = verb_root(word)
    direct = None
    for group, response in DIRECT_VERBS:
        if current_root in group:
            direct = response
    if direct is not None:
        base, inflected, linked = direct
        value += base
        if current_root != word.lower():
            value += inflected
        if previous in ('to', 'that', 'which', 'should', 'will',
                        'would', 'can', 'must', 'just'):
            value += linked
        if current_root == 'return' and word[:1].isupper():
            value -= 0.39
        line = tail.rsplit('\n', 1)[-1]
        if re.search(r'#|//|/\*|\*|"""|@return', line):
            value -= 0.48

    if word == 'with':
        value -= 0.06
        if previous in COLLECTIONS or previous in (
            'string', 'plot', 'file', 'clone', 'template',
            'distribution', 'object', 'dataframe'
        ):
            value -= 1.1
    if word == 'by' and previous in (
        'formed', 'indexed', 'followed', 'joined', 'taking', 'generated',
        'spanned', 'constructed', 'composed', 'built', 'constituted'
    ):
        value -= 0.97
    if word in ('on', 'over'):
        value += 0.0 if word == 'on' else -0.19
        if previous.endswith('ing') or previous in (
            'trained', 'operates', 'operate', 'iterator', 'functor',
            'function', 'operator', 'loop'
        ):
            value -= 0.17
    if text == '<tool_response>':
        value -= 0.5
    return (doc, (tail + text)[-100:]), float(value)

"""A formatting heuristic for boundaries of heading-like phrases.

Capitalized, relatively unpunctuated lines get positive boundary responses,
stronger after blank lines. Parenthetical, attribution and title separators
also respond after short capitalized phrases. Short non-ASCII headings have
a smaller fallback response. This uses appearance, not the heading's meaning.

Ordinary text is zero. Document starts have a coarse word-shape correction,
with separate responses for indentation, a bullet, and the initial Title:
field. Only the recent line, previous token and document position are kept.
"""
READS = ()
JOINERS = frozenset('of and the in to for a on with'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, line, breaks = 0, '', '', 0
    else:
        _, age, previous, line, breaks = carry

    before = line + s.split('\n', 1)[0]
    stripped = before.strip()
    words = stripped.split()
    token = s.strip()
    value = 0.0
    if age == 0:
        if s == '\t':
            value = 1.905
        elif not token and '\t' in s:
            value = 0.74 if '\n' in s else 0.87
        elif token == '•':
            value = 0.857
        elif s.startswith(' '):
            value = -0.40
        elif token.isalpha():
            value = -0.62 if token.isascii() else -0.36
        else:
            value = -0.58 if token.islower() else -0.32
    elif age == 1 and previous == 'Title' and s == ':':
        value = 8.905
    elif token in {'(', '|', '-', '–', '—', 'by'}:
        heading = line.strip()
        phrase = heading.split()
        if (2 <= len(phrase) <= 16 and len(heading) <= 160
                and not heading.isupper()
                and not any(c in '.!?:;,。！？：' for c in heading)
                and sum(w[0].isupper() for w in phrase) >= len(phrase) / 2):
            value = 0.45
    elif words and ('\n' in s or token[-1:] in (':', ';', '：', '；')):
        capitals = sum(w[0].isupper() for w in words) / len(words)
        if capitals >= 0.5:
            punctuation = any(c in '.!?:;,。！？：' for c in stripped)
            if punctuation:
                if capitals < 0.65:
                    value = 0.066
                else:
                    value = 0.093 if len(previous) <= 3 else 0.21
            else:
                title = all(w[0].isupper() or w.lower() in JOINERS
                            for w in words)
                if not title:
                    value = 0.267
                elif stripped.isupper():
                    value = 0.218
                elif breaks >= 2:
                    value = 0.902 if s.count('\n') <= 1 else 0.569
                else:
                    value = 0.62 if previous.startswith(' ') else 0.346
        elif '\n' in s and not any(c in '.!?:;,。！？：' for c in stripped):
            letters = sum(c.isalpha() for c in stripped) / max(len(stripped), 1)
            if breaks >= 2 and stripped[0].isupper() and len(stripped) <= 120:
                value = 0.25
            elif not stripped.isascii() and len(stripped) <= 17 and letters > 0.85:
                value = 0.25

    if '\n' in s:
        breaks = s.count('\n') + (breaks if not stripped else 0)
        line = s.rsplit('\n', 1)[-1]
    else:
        line = (line + s)[-500:]
    return (doc, age + 1, s, line, breaks), value
